/* 自动生成：REF_CCMD3 诊断标准数据（_refdata/bundle.js 合并 2 个 chunk） */
window.REF_CCMD3 = [{"code":"00","name":"阿尔茨海默（Alzheimer）病","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"阿尔茨海默病（Alzheimer）病是一组病因未明的原发性退行性脑变性疾病。多起病\n于老年期，潜隐起病，缓慢不可逆地进展（2 年或更长），以智能损害为主。病理改变主\n要为皮层弥漫性萎缩，沟回增宽，脑室扩大，神经元大量减少，并可见老年斑、神经元纤\n维缠结、颗粒性空泡小体等病变，胆碱乙酰化酶及乙酰胆碱含量显著减少。起病在65 岁\n以前者（老年前期），多有同病家族史，病变发展较快，颞叶及顶叶病变较显著，常有失\n语和失用。"},{"section":"症状标准","text":"1  符合器质性精神障碍的诊断标准；\n2  全面性智能性损害；\n3  无突然的卒中样发作，疾病早期无局灶性神经系统损害的体征；\n4  无临床或特殊检查提示智能损害是由其他躯体或脑的疾病所致；\n5  下列特征可支持诊断但不是必备条件：（1）高级皮层功能受损，可有失语、失认可\n失用；（2）淡漠、缺乏主动性活动，或易激惹和社交行为失控；（3）晚期重症病例可能出\n现巴金森症状和癫痫发作；（4）躯体、神经系统，可实验室检查证明有脑萎缩；\n6  尸体或神经病理学检查有助于确诊。"},{"section":"严重标准","text":"日常生活和社会功能明显受损。"},{"section":"病程标准","text":"起病缓慢，病情发展虽可暂停，但难以逆转。"},{"section":"排除标准","text":"排队脑血管病等其他脑器质性病变所致智能损害、抑郁症等精神障碍所致的\n假性痴呆、精神发育迟滞，或老年人良性健忘症。"},{"section":"说明","text":"阿尔茨海默病性痴呆可与血管性痴呆共存，如果脑血管病发作叠加于阿尔茨海默\n病的临床表现和病史之上，可引起智能损害症状的突然变化，这些病例应作双重诊断（和\n双重编码）。如血管性痴呆发生在阿尔茨海默病之前，根据临床表现也许无法作出阿尔茨\n海默病的诊断。"}]},{"code":"00.1","name":"阿尔茨海默病，老年前期型","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"诊断标准","text":"1  符合阿尔茨海默病的诊断标准，发病年龄小于65 岁；\n2  有颞叶、顶叶、或额叶受损的证据，除记忆损害外，可较早产生失语（遗忘性或感\n觉性）、失写、失读、失算，或失用等症状；\n3  发病较急，呈进行性发展。"},{"section":"说明","text":"包括阿尔茨海默病2 型，早老病所致精神障碍，阿尔茨海默型。"}]},{"code":"00.2","name":"阿尔茨海默病 老年型","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"诊断标准","text":"1  符合阿尔茨海默病的诊断标准，发病在65 岁以后；\n2  以记忆损害为主的全面智能损害；\n3  潜陷起病，呈非常缓慢的进行性发展。"},{"section":"说明","text":"老年型和老年前期型之间并无明确界线。老年前期型可发生于较高的年龄；反之，\n老年型偶尔也可发生在65 岁发前。"}]},{"code":"00.3","name":"阿尔茨海默病，非典型或混合型","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"1  符合阿尔茨海默病的诊断标准；\n2  临床表现不典型，如65 岁以后起病却具有老年前期型临床特征或同时符合脑血管病\n所致痴呆的诊断标准，但又难以作出并列诊断者，可使用本编码。"}]},{"code":"00.9","name":"其他或待分类的阿尔茨海默病","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"阿尔茨海默病无法确定为哪一型时作本编码。"}]},{"code":"01","name":"脑血管病所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"在脑血管壁病变基础上，加上血液成分或血液动力学改变，造成脑出血或缺血，导致\n精神障碍。一般进展较缓慢，病程波动，常因卒中引起病情急性加剧，代偿良好时症状可\n缓解，因此临床表现多种多样，但最终常发展为痴呆。"},{"section":"症状标准","text":"1  符合器质性精神障碍的诊断标准；\n2  认知缺陷分布不均，某些认知功能受损明显，另一些相对保存，如记忆明显受损，\n而判断、推理，及信息处理可只受轻微损害，自知力可保持较好；\n3  人格相对完整，但有些病人的人格改变明显，如自我中心、偏执、缺乏控制力、淡\n漠，可易激惹；\n4  至少有下列1 项局灶性脑损伤的证据：脑卒中史、单侧肢体痉挛瘫痪、伸跖反射阳\n性，或假性球麻痹；\n5  病史、检查，可化验有脑血管病证据\n6  尸检或大脑神经病理学检查有助于确诊。"},{"section":"严重标准","text":"日常生活和社会功能明显受损。"},{"section":"病程标准","text":"精神障碍的发生、发展，及病程与脑血管疾病相关。"},{"section":"排除标准","text":"排除其他原因所致意识障碍、其他原因所致智能损害（如阿尔茨海默病）、情\n感性精神障碍、精神发育迟滞、硬脑膜下出血。"},{"section":"说明","text":"脑血管病所致精神障碍可与阿尔茨海默病痴呆共存，当阿尔茨海默病的临床表现\n叠加脑血管病发作时，可并列诊断。"}]},{"code":"01.1","name":"急性脑血管病所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"通常是在多次卒中后迅速发生的精神障碍，偶可由1 次大量脑出血所致，此后记忆和\n思维损害突出。典型病例有短暂脑缺血发作史，并有短暂意识障碍、一过性轻度瘫痪或视\n觉丧失。多在晚年起病。"},{"section":"诊断标准","text":"1  符合脑血管病所致精神障碍的诊断标准；\n2  通常在多次脑卒中之后或偶尔在1 次大量出血后迅速发展为智能损害；\n3  通常在1 个月内发展为痴呆（一般不超过3 个月）。"}]},{"code":"01.2","name":"皮层性血管病所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"常在50~60 岁起病，约半数并发高血压病，以智能阶梯性恶化为主。可在某次短暂脑\n缺血发作后突然或逐渐起病。智能损害往往由脑血管病导致的脑梗塞所致。一般是颈动脉\n内膜\n粥样硬化致微栓子脱落，引起脑内动脉小分支梗塞。梗塞往往较小，一般进展缓慢。常因\n脑出血、脑梗塞或脑血栓形成导致卒中发作，引起病情急性加剧，病程波动，因此病人可\n有多次短暂的脑缺血卒中史，局限性神经系统症状体征，如一过性轻瘫、失语、视力障碍\n等。精神症状多种多样，智能损害较长时期为局限性，最终发展为全面痴呆。脑组织常有\n多个较小的腔隙性梗塞灶。"},{"section":"诊断标准","text":"1  符合脑血管病所致精神障碍的诊断标准；\n2  有脑血管病的证据，如多次缺血性卒中发作，局限性神经系统损害，及脑影像检查，\n如CT、MRI 检查有阳性所见；\n3  在数次脑实质的小缺血性发作后，逐渐发生智能损害。早期为局限性智能损害，人\n格相对完整，晚期有人格改变，并发展为全面性痴呆；\n4  起病缓慢，病程波动或呈阶梯性，可有临床改善期，通常在6 个月内发展为痴呆。"},{"section":"说明","text":"包括多发脑梗塞性痴呆。"}]},{"code":"01.3","name":"皮层下血管病所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"诊断标准","text":"1  符合脑血管病所致精神障碍的诊断标准；\n2  病变主要位于大脑半球深层白质，而大脑皮层保持完好。"}]},{"code":"01.4","name":"皮层和皮层下血管病所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"根据临床特点和检查证明脑血管所致精神障碍系皮层和皮层下混合损害所致。"}]},{"code":"01.9","name":"其他或待分类血管病所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[]},{"code":"02","name":"其他脑部疾病所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"由阿尔茨海默病或脑血管病以外的脑部疾病导致的精神障碍，推测起病直接由脑部疾\n病所致。"},{"section":"症状标准","text":"1  符合器质性精神障碍的诊断标准；\n2  有躯体、神经系统和实验室检查的阳性所见或相关脑部疾病；\n3  下列疾病使发生本类精神障碍的风险增加：脑变性病、脑炎、脑外伤、脑瘤、脑寄\n生虫病，或癫痫等；\n4  无精神障碍由其他原因引起的证据（如家族史强阳性可作为原因的应激因素）；\n5  尸检或大脑神经病理学检查有助于确诊。"},{"section":"严重标准","text":"日常生活或社会功能受损。"},{"section":"病程标准","text":"精神障碍的发生、发展，及病程与原发性脑部疾病有关。"},{"section":"病程标准","text":"排除其他原因所致意识障碍、其他原因所致智能损害（如阿尔茨海默病或血\n管性痴呆）、精神活物质所致精神障碍、情感性精神障碍，或精神发育迟滞。"}]},{"code":"02.1","name":"脑变性病所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"诊断标准","text":"1  符合器质性精神障碍的诊断标准；\n2  有躯体、神经系统，及实验室检查证明系相关脑变性病所致；\n3  下列疾病使发生本类精神障碍的风险增加：匹克病、亨廷顿病、巴金森病、肝豆状\n核变性等；"}]},{"code":"02.2","name":"颅内感染所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"颅内感染指由某种感染源（包括病毒、细菌、立克次体、螺旋体、寄生虫等）引起的\n颅内的炎症。颅内的实质、脑膜及血管等均可被感染。根据受侵犯的主要部位，可分为两\n大类：（1）主要侵犯脑实质者，称为脑炎；（2）主要侵犯软脑膜者，称为脑膜炎。如果脑\n实质和脑膜两者均明显受损称为脑膜脑炎。散发性脑炎以往报道较多，目前认为是一组具\n有急性脑症状的多种病因所致的脑部疾病的总称，其中大部分为病毒性脑炎和变态反应性\n急性脱髓鞘脑病。前一类经病毒及血清学证实的有单纯疱疹病炎等，以单纯疱疹病毒性脑\n炎最为常见；后一类经病理证实的有同心圆性硬化等，还有一些不明病因的脑部疾病。由\n上述感染源直接侵犯脑组织导致的精神障碍称为颅内感染所致精神障碍，本章仅纳入急性\n病毒性脑炎和慢病毒感染的克—雅病所致精神障碍。"},{"section":"症状标准","text":"1  符合器质性精神障碍的诊断标准；\n2  躯体、神经系统，及实验室检查证明系相关颅内感染所致；\n3  无精神障碍由其他原因导致的足够证据；\n4  尸检可大脑神经病理学检查有助于确诊。"},{"section":"严重标准","text":"日常生活或社会功能受损。"},{"section":"病程标准","text":"精神障碍的发生、发展，及病程与脑内感染相关。"},{"section":"排除标准","text":"排除其他原因所致意识障碍、其他原因所致智能损害、精精神活性物质所致精\n神障碍、情感性精神障碍，或精神发育迟滞。"}]},{"code":"02.3","name":"脱髓鞘脑病所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"脱髓鞘疾病是一组病理改变以神经脱髓鞘为主的获得性疾病，而轴突和神经细胞很少\n损害。发生于中枢神经系统的脱髓鞘疾病称脱髓鞘脑病。主要有：（1）急性播散性脑脊髓\n炎（ADEM）和急性出血性白质脑炎（AHLE）；（2）多发性硬化及过渡型，如弥漫性硬化\n（Schilder 病）；（3）脑白质营养不良，是先天遗传性神经髓鞘磷脂代谢的相关酶障碍导致\n的髓鞘发育形成异常，有人将其归入脂质沉积症。CCMD-3 仅纳入（1）急性播散性脑脊\n髓炎和急性出血性白质脑炎；（2）多发性硬化。"}]},{"code":"02.5","name":"脑瘤所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"由脑瘤侵犯脑实质，压迫邻近的脑组织或脑血管，造成脑实质破坏或颅内压增高所致\n的精神障碍。"},{"section":"诊断标准","text":"1  符合器质性精神障碍的诊断标准；\n2  有脑瘤的证据，且精神障碍的发生、发展，及病程与脑瘤相关。"}]},{"code":"02.6","name":"癫痫所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"指一组反复发作的脑异常放电导致的精神障碍。由于累及的部位和病理生理改变不同，\n导致的精神症状各异。可分为发作性的持续性精神障碍两类。前者为一定时间内的感觉、\n知觉、记忆、思维等障碍，心境恶劣，精神运动性发作，可短暂精神分裂症样发作，发作\n具有突然性、短暂性，及反复发作的特点；后者为分裂症样障碍、人格改变，可智能损害\n等。"},{"section":"症状标准","text":"1  符合器质性精神障碍的诊断标准；\n2  在原发性癫痫的证据；\n3  精神障碍的发生及其病程与癫痫相关。"},{"section":"严重标准","text":"社会功能受损。"},{"section":"病程标准","text":"分发作性和持续性两类病程。前者有突然性、短暂性，及反复发作的特点；\n后者（如分裂症样障碍、人格改变，或智能损害等）为迁延必病程。"},{"section":"排除标准","text":"1  排除感染或中毒所致精神障碍，需注意它们可产生继发性癫痫；\n2  排除癔症、睡行症、精神分裂症、情感性精神障碍。"},{"section":"说明","text":"如系继发性癫痫，应按原发疾病所致精神障碍下诊断。如能确定癫痫发作类型者，还应\n按癫痫国际分类（表1）\n表1。癫痫发作的国际分类（已简化）\n一、开始的部分性发作：\n（1）伴意识障碍的单纯部分性发作（局灶性癫痫）：①运动性；②感觉性；③植物神经\n性；④精神性。\n（2）有意识障碍的复杂部分性发作（相当于颞叶癫痫发作）：①意识障碍起病；②单纯\n部分性发作起病进而意识障碍。\n（3）部分性发作起病进而全身必发作：①单纯部分性发作起病进而全身性发作；②复\n杂部分性发作开始的全身性发作。\n二、并非从部分性发作开始的全身性发作：\n（1）失神发作（癫痫小发作）；\n（2）肌阵挛性发作；\n（3）阵挛性发作；\n（4）强直性发作；\n（5）强直一阵挛性发作（癫痫大发作）；\n（6）无张力性发作（癫痫迟缓性发作）；\n三、未分类发作"}]},{"code":"02.9","name":"以上未分类的其他脑部疾病所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"呆]\n以上未分类的其他脑部疾病也可导致精神障碍，为指明原发疾病应加上有关的ICD-10\n编码。如大脑脂沉积症[E75.-]、麻痹性痴呆[A52.-]等。以上未分类的脑部疾病所致精神障\n碍，无法确定为哪一型（待分类）时也用本编码。"}]},{"code":"02.11","name":"匹克（Pick）病所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"是起始于中年（常在50~60 岁之间）的脑变性病导致的精神障碍，先是缓慢发展的行\n为异常、性格改变，或社会功能衰退，随后出现智能、记忆，及言语功能损害，偶可伴有\n淡漠、欣快，及锥体外系症状。神经病理学改变为选择性额叶或颞叶萎缩，而老年斑及神\n经原纤维缠结的数量未超出正常老龄化进程。"},{"section":"诊断标准","text":"1  符合脑变性病所致精神障碍的诊断标准，在疾病早期记忆和顶叶功能相对完整；\n2  以额叶受损为主，至少有下列2 项：（1）情感迟钝或欣快；（2）社交行为粗鲁、不\n能安静，或自控能力差；（3）失语；\n3  缓慢起病，逐步衰退；\n4  排除阿尔茨海默病、脑血管病所致精神障碍，或继发于其他脑部疾病的智能损害。"}]},{"code":"02.12","name":"亨廷顿（Huntington）病所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"亨廷顿病系常染色体单基因显性遗传病，常在20~30 岁左右舞蹈样运动。早期以额叶\n功能紊乱为主，到晚期记忆仍可相对完整，智能损害只是本病症状之一。部分病例早期表\n现为抑郁、焦虑，或明显偏执的人格改变。病程进展缓慢，常在10~15 年内死亡。根据舞\n蹈样运动、智能损害，及亨廷顿病家族史可作诊断。"},{"section":"诊断标准","text":"1  符合脑变性病所致精神障碍的诊断标准；\n2  皮层下功能常先受损，如以思维迟缓、运动迟缓，或以淡漠、抑郁的人格改变为特\n征；\n3  不自主舞蹈样动作，可伴有僵硬或锥体束性痉挛；\n4  父母或兄弟姐妹中有亨廷顿病，或提示有本病家族史；\n5  疾病进展缓慢，常在10~15 年内死亡；\n6  排除其他舞蹈性运动障碍、匹克病，或克一雅病。"}]},{"code":"02.13","name":"巴金森（Parkinson）病所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"巴金森病的原因尚未阐明，主要表现为运动减少、肌强直、震颤、面具脸及姿势障碍\n等，重者可导致痴呆。多见于中老年人，平均发病年龄在60 岁左右，男性较多。"},{"section":"诊断标准","text":"1  符合脑变性病所致精神障碍的诊断标准；\n2  先有肌张力亢进、震颤、面具脸等巴金森病表现，然后发生精神障碍，严重时导致\n痴呆；\n3  慢性进行性病程；\n4  排除抗巴金森症治疗导致的认知损害和其他原发性脑部所致精神障碍。"},{"section":"说明","text":"巴金森病痴呆可能与阿尔茨海默病痴呆或脑血管病所致痴呆同时存在。"}]},{"code":"02.14","name":"肝豆状核变性（Wilson）病所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"呆]\n肝豆状核变性是一种常染色体单基因隐性遗传病，由铜代谢障碍导致肝、脑、角膜等\n组织铜沉积引起病变。临床表现震颤、肌强直、言语不清、强制性哭笑，以及肝硬化等，\n角膜可出现K-F（Kayer-Fleischer）环。精神障碍以智能减退、情绪激动，或淡漠等较多\n见，少数患者有幻觉、妄想、或人格改变。多见于少年到壮年。"},{"section":"诊断标准","text":"1  符合脑变性病所致精神障碍的诊断标准；\n2  有肝硬化、肌张力增加、震颤、角膜K-F 环等症状体征；\n3  有进行性智能减退、情感障碍、幻觉、妄想，或人格改变等精神症状；\n4  实验室检查有铜代谢障碍的证据。"}]},{"code":"02.21","name":"急性病毒性脑炎所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"症状标准","text":"1  符合颅内感染所致精神障碍的诊断标准；\n2  出现意识障碍前，常有呼吸道或消化道感染史，可有明显的精神运动性紊乱；\n3  至少有下列1 项智能损害或神经系统症状：肌张力增高、偏瘫、腱反射亢进、病理\n反射阳性、脑膜刺激症状、植物神经症状、颞叶或额叶损害；\n4  EEG 或颅脑CT 检查异常；\n5  实验室检查：病毒分离、聚合酶链反应（PCR），或病毒抗体测定（如免疫酶联吸附\n分析法，简称ELISA）阳性。"},{"section":"严重标准","text":"日常生活或社会功能受损。"},{"section":"病程标准","text":"急性或亚急性起病，精神障碍的发生、发展，及病程与颅内感染相关。"},{"section":"排除标准","text":"1  排除功能性精神障碍、其他颅内感染性精神障碍；\n2  本病有颅内占位性病变症状时，应作CT 等检查与脑瘤鉴别。"}]},{"code":"02.22","name":"克—雅（Creutzfeldt-Jacob）病所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"克一雅病是由朊病毒导致的一种亚急性海绵状脑病，以进行性加重的神经精神症状为\n主，如肢体的进行性痉挛性瘫痪和肌萎缩，伴锥体外系体征和舞蹈症性手足徐动样运动。\n还可有共济失调、失明，或肌纤维震颤。可见于任何成年期，但通常在40 多岁起病。病\n程为亚急性，1~2 年内导致死亡。某些病例（如肌萎缩型）的神经系统体征可先于智能损\n害。"},{"section":"诊断标准","text":"1  符合颅内感染所致精神障碍的诊断标准；\n2  在智能损害发生前或早期，就有神经系统体征出现。如锥体束征、肌阵挛，或肌萎\n缩，还可有失语、视觉损害、锥体外系体征，或小脑体征。晚期常出现运动不能和缄默；\n3  锥体和锥体外系病症伴肌阵挛，及特征三相脑电图（在一个慢波和低电压背景下出\n现周期性尖波）更有助诊断；\n4  神经病理学检查有助于确诊；\n5  病程为亚急性，迅速发展，可在1~2 年内死亡；\n6  排除阿尔茨海默病、匹克病，巴金森病，或脑炎后巴金森症等。"}]},{"code":"02.23","name":"脑炎后综合征","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"诊断标准","text":"1  符合颅内感染所致精神障碍的诊断标准；\n2  至少有下列1 项脑炎后的残留症状：（1）周身不适、淡漠，或易激惹；（2）某些认\n知功能的低下（如学习困难）；（3）睡眠一觉醒形式障碍；（4）性行为改变；\n3  至少有下列1 项后遗的神经系统体征：瘫痪、失聪、失语、结构性失用，或运算不\n能。"}]},{"code":"02.31","name":"急性播散性脑脊髓炎和急性出血性白质脑炎所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"特定疾病所致痴呆\n都是脑和脊髓广泛受损的急性炎性脱髓鞘疾病，常发生于：（1）病毒感染或接处疫苗\n后，可能是感染或接种疫苗引发的中枢髓鞘的自身免疫性疾病，又称感染后脑脊髓炎或疫\n苗接种后脑脊髓炎；（2）特发性急性播散性脑脊髓炎。国内曾报道的“散发性脑炎”，部分\n为本病。"},{"section":"症状标准","text":"1  符合器质性精神障碍的诊断标准；\n2  至少有下列1 项神经精神症状：（1）脑膜损害症状，如头痛、呕吐、脑膜刺激征；\n（2）脑实质弥漫损害症状，如意识障碍、精神症状、癫痫发作、颅内压增高等，甚至去\n大脑强直；（3）脑实质局灶损害症状如瘫痪、视野或视力障碍、不自主运动；（4）脑干损\n害症状，如脑神经和肢体交叉性麻痹；（5）小脑损害症状，如共济失调；（6）脊髓损害症\n状，如截瘫、传导束型感觉障碍及大小便障碍，少数有上升麻痹或周围神经损害表现；\n3  实验室检查：ADEM 脑脊液蛋白质轻至中度增加（多为IgG），可出现寡克隆区带，\n急性期可测出髓鞘碱性蛋白（MBP）及其抗体。EEG 呈弥漫性慢波增多，常为高波幅\n4—6Hzθ 波。脑CT 扫描显示白质内弥散性、多灶性、斑状或大片状低密度区。"},{"section":"严重标准","text":"日常生活可社会功能受损，可后遗运动或智能障碍、精神异常或癫痫发作。"},{"section":"病程标准","text":"精神障碍的发生、发展，及病程与原发病变相关。ADEM 急性期约为2 周，\n多数可完全可基本恢复。AHLE 严重病例病性可呈爆发性进展，在2~4 天、甚至数小时内\n死亡。"},{"section":"排除标准","text":"排除功能性精神障碍、病毒性脑脊髓炎、感染中毒性脑病，或其他病因所致\n的脑脊髓病。"}]},{"code":"02.32","name":"多发性硬化所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"多发性硬化指以中枢神经系统炎性脱髓鞘为特征的自身免疫性疾病。临床特征是多发\n性病灶和反复发作与缓解的病程。病变常侵犯脑室周围的白质、视神经、脊髓的传导束、\n脑干，及小脑、可能是某些易感个体因先天遗传因素具有产生免疫调节功能紊乱的倾向，\n加上后天因素（如麻疹病毒感染）促发髓鞘成分的异常，引起自身免疫反应。发病多在\n20~40 岁，女性较多。急性型起病者呈急性或亚急性出现大脑、脑干、小脑，及脊髓等处\n多灶性损害表现，如意识障碍、抑郁、欣快、智能损害等精神症状，及瘫痪、锥体束征、\n病理反射阳性、脑神经损害、视力障碍，甚至强直性抽搐或去皮质状态等神经症状。病程\n短暂，在几周至几月内症状进展而死亡。我国曾报道“散发性脑炎”的部分病例，尸检证实\n为急性多发性硬化。"},{"section":"诊断标准","text":"1  符合器质性精神障碍的诊断标准；\n2  至少有下列1 项神经系统症状：脊髓性感觉障碍、视力下降（如急性视神经炎）、步\n行困难、无力、复视、平衡障碍、共济失调；慢性病例有眼球震颤（如为旋转性则高度提\n示本病之可能）、痛性强直性痉挛发作，或其他发作性症状（如三叉神经痛等）；\n3  至少有下列1 项精神症状：抑郁或欣快、记忆或智能损害；\n4  实验室检查：脑脊液免疫球蛋白G(IgG)增高，轻链中 k 与λ 比值异常。IgG 髓鞘内\n每24 小时合成量增高，IgG 指数增高。脑脊液等电聚焦或聚丙烯酰胺电泳可见寡克隆抗\n体的区带。活动期可有MBP 抗体增多。可有视觉、听觉及体感告示诱发电位异常，如潜\n伏期延发；脑影像检查（CT、MRI）异常；\n5  急性或亚急性起病，急性者类似卒中，在数小时或数日内出现局灶性症状，缓慢发\n病者可在1 周至1 个月内病情明显。精神障碍的发生、发展，及病程与原发病变相关。"}]},{"code":"02.41","name":"脑震荡后综合征F07.2","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"症状标准","text":"1  符合脑外伤所致精神障碍的诊断标准；\n2  有脑外伤导致不同程度的意识障碍病史；\n3  目前的症状与脑外伤相关，并至少有下列3 项：（1）头痛、眩晕、内感性不适，或\n疲乏；（2）情绪改变，如易激惹、抑郁，或焦虑；（3）主诉集中注意困难、思考效率低，\n或记忆损害，但是缺乏客观证据（如心理测验正常）；（4）失眠；（5）对酒的耐受性降低；\n（6）过分担心上述症状，一定程度的疑病性超价观念和采取病人角色；\n4  中枢神经系统和脑CT 检查，不能发现弥漫性或局灶性损害征象。"},{"section":"严重标准","text":"社会功能受损。"},{"section":"病程标准","text":"符合症状标准和严重标准至少已3 个月。"},{"section":"排除标准","text":"排除脑挫裂伤后综合征、分裂症、情感性精神障碍，可创伤后应激障碍。"}]},{"code":"02.42","name":"脑挫裂伤后综合征","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"脑挫裂伤是头颅受外力直接作用产生的器质性损伤，其特征为严重持久的意识障碍历\n时30 分钟以上。以全脑损伤症状为主，可并有局灶性症状、继发蛛网膜下腔出血，或颅\n内血肿。由脑挫裂伤导致的后遗神经症性症状称脑挫裂伤后综合征。"},{"section":"症状标准","text":"1  符合脑外伤所致精神障碍的诊断标准；\n2  脑挫裂伤导致严重持久的意识障碍历时30 分钟以上；\n3  目前症状与脑挫裂伤相关，并符合“02.41 脑震荡后综合征的症状标准（3）”\n4  中枢神经系统和脑CT 检查发现弥漫性或局灶性损害征象、继发蛛网下腔出血，或\n颅内血肿。"},{"section":"严重标准","text":"社会功能受损。"},{"section":"病程标准","text":"符合症状标准和严重标准至少已3 个月。"},{"section":"排除标准","text":"排除脑震荡后综合征、分裂症、情感性精神障碍，或创伤后应激障碍。"}]},{"code":"03","name":"躯体疾病所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"指由各种躯体疾病，如躯体感染、内脏器官疾病、内分泌障碍、营养代谢疾病等影响\n脑功能所致的精神障碍。急性躯体疾病常引起急性脑病综合征（如谵妄），慢性躯体疾病\n则引起慢性脑病综合征（如智能损害、人格改变等）。从急性过渡到慢性期间，可有抑郁、\n躁狂、幻觉、妄想、兴奋、木僵等精神症状，并在躯体疾病的整个病程中，具有多变和错\n综复杂的特点。"},{"section":"症状标准","text":"1  通过病史、躯体，及神经系统检查、实验室检查发现躯体疾病的证据；\n2  精神障碍的发生、发展，及病程与原发躯体疾病相关，并至少有下列1 项：\n① 智能损害；\n②遗忘综合征；\n③人格改变;\n④意识障碍（如谵妄）；\n⑤精神病性症状（如幻觉、妄想、或紧张综合征等）；\n⑥情感障碍（如抑郁或躁狂综合征等）；\n⑦神经症样症状；\n⑧以上症状的混合状态或不典型表现；\n3  无精神障碍由其他原因导致的足够证据（如酒精或药物滥用、应激因素）。"},{"section":"严重标准","text":"社会功能受损。"},{"section":"病程标准","text":"精神障碍的发生、发展及病程与原发性躯体疾病相关。"},{"section":"排除标准","text":"排除精神分裂症、情感性精神障碍的严重躁狂发作或抑郁发作。"}]},{"code":"03.1","name":"躯体感染所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"指由病毒、细菌、螺旋体、真菌、原虫或其他感染病原体所致的全身感染（如从类免\n疫缺陷病毒（HIV）感染、败血症、钩端螺旋体病、恶性疟疾、血吸虫病）所致精神障碍。\n无颅内感染的证据。诊断时应标明某种感染性疾病所致精神障碍。"},{"section":"症状标准","text":"1  符合躯体疾病所致精神障碍的诊断标准；\n2  有明显的感染史；\n3  在体检或细菌学检查中可发现与感染相关的症状、体征与实验室检查所见。"},{"section":"严重标准","text":"社会功能受损。"},{"section":"病程标准","text":"精神障碍的发生、发展及病程与原发性感染相关。"},{"section":"排除标准","text":"排除其他疾病的意识障碍，如中毒性谵妄、癔症样意识障碍等；排除精神分\n裂症。"}]},{"code":"03.2","name":"内脏器官疾病所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"由心、肺、肝、肾等内脏器官疾病引起脑供血、供氧不足、代谢产物积累，或水与电\n解质紊乱，继发脑功能紊乱导致的精神障碍。精神症状随原发疾病的严重程度变动。如能\n明确内脏器官疾病，则命名为该病所致精神障碍，如03.21 心脑综合征、03.22 肺脑综合\n征等。"},{"section":"诊断标准","text":"1  符合躯体疾病所致精神障碍的诊断标准；\n2  有脏器病变的证据，精神症状随原发疾病的严重程度变动。"}]},{"code":"03.3","name":"内分泌疾病所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"由内分泌疾病引起内分泌功能亢进或低下导致的精神障碍。可分为3 类：\n①内分泌\n疾病本身引起精神障碍，特征是情感激越或迟钝，食欲、性欲、睡眠等本能活动亢进或减\n退，人格改变和精神活动的周期性改变。一般无智能损害；②疾病严重影响脑代谢，造成\n急性脑病，如甲状腺危象、糖尿病性昏迷等；③慢性内分泌疾病常造成持续的弥漫性脑病，\n导致慢性脑病综合征。编码用03.3x 方式，如03.31 经前期紧张综合征、03.32 更年期综合\n征。能明确内分泌疾病性质者，则命名为该病所致精神障碍，如03.34 甲状腺机能减退所\n致精神障碍等。"},{"section":"诊断标准","text":"1  符合躯体疾病所致精神障碍的诊断标准；\n2  有内分泌疾病和内分泌功能亢进或低下的证据，精神症状随原发疾病的严重程度变\n动。"}]},{"code":"03.4","name":"营养代谢疾病所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"诊断标准","text":"1  符合躯体疾病所致精神障碍的诊断标准；\n2  并有营养代谢疾病的证据，精神症状随原发疾病的严重程度变动。"}]},{"code":"03.5","name":"结缔组织疾病所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"常见的结缔组织疾病有系统性红斑狼疮、结节性动脉周围炎、皮肌炎多发性肌炎、硬\n皮症，及白塞病等。临床表现以精神障碍为主的有播散性红斑狼疮；以持续性疼痛为主的\n有慢性风湿关节炎和白塞病等。"},{"section":"诊断标准","text":"1  符合躯体疾病所致精神障碍的诊断标准；\n2  有结缔组织疾病的证据，精神症状随原发疾病的严重程度变动。"}]},{"code":"03.6","name":"染色体异常所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"诊断标准","text":"1  符合躯体疾病所致精神障碍的诊断标准；\n2  并有染色体异常的证据，精神症状随原发疾病的严重程度变动。"}]},{"code":"03.7","name":"物理因素所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"诊断标准","text":"1  符合躯体疾病所致精神障碍的诊断标准；\n2  并有物理因素所致疾病的证据，精神症状随原发疾病的严重程度变动。"}]},{"code":"03.9","name":"以上未分类的其他躯体疾病所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"呆\n以上未分类的其他躯体疾病所致精神障碍无法确定为哪一型时用本编码。"}]},{"code":"03.11","name":"人类免疫缺陷病毒（HIV）所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"艾滋病是由一种逆转录病毒导致的传染病，主要通过性接触或血及血制品等传染，导\n致人体免疫功能障碍。本病的智能损害主要有健忘、注意力不集中、解决问题困难和阅读\n困难。其他精神症状，如淡漠、主动性减少、社会性退缩也很常见，少数出现情感障碍、\n精神病性症状，或癫痫发作。躯体检查常发现震颤、共济失调、肌张力增强、腱反射普遍\n亢进、额叶脱抑制综合征、眼球追踪障碍。一般迅速（数周或数月）发展成严重的精神衰\n退、缄默进鸸死亡。"},{"section":"诊断标准","text":"1  符合躯体感染所致精神障碍的诊断标准，并有HIV 感染的证据；\n2  不能作其他原因解释精神障碍。"},{"section":"说明","text":"包括艾滋病所致痴呆。"}]},{"code":"03.51","name":"系统性红斑狼疮所致精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"系统性红斑狼疮是一种病因未明的结缔组织疾病，病程反复迁延，病变损害皮肤、血\n管、内脏器官，及神经系统，表现为多形性水肿（如鼻梁及两颊间蝶形红斑）、发热、出\n血、淋巴结肿大；本病的精神症状出现较早，可有幻觉、妄想、躁狂或抑郁综合征，或意\n识障碍等；神经系统症状可有癫痫发作、偏瘫、失语，及颅内压升高等。血象可见红斑狼\n疮细胞。"},{"section":"症状标准","text":"1  符合躯体疾病所致精神障碍的诊断标准，并至少有下列1 项：\n①\n意识障碍；\n②\n幻觉、妄想综合征，及其他分裂症样症状{如类似青春型分裂症的兴奋、幼稚行为}；\n③\n躁狂综合征；\n④\n智能损害多在后期发生；\n2  精神障碍的发生、发展及病程与原发的系统性红斑狼疮相关；\n3  至少有下列1 项神经系统症状或病变：癫痫发儿、眼球震颤、眼肌麻痹、视神经萎\n缩、面瘫、球麻痹、偏瘫、重症肌无力、舞蹈样运动、蛛网膜下腔出血、横贯性脊髓病变\n等；\n4  实验室检查：血象见红斑狼疮细胞、抗核抗体ANA90%~99%阳性。"},{"section":"严重标准","text":"社会功能受损。"},{"section":"病程标准","text":"起病较急，呈进行性、波动性病程。"},{"section":"排除标准","text":"其他结缔组织疾病所致精神障碍，如结节性动脉周围炎、皮肌炎、多发性肌\n炎、硬皮症，及白塞病等。"}]},{"code":"03.91","name":"围生期精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[]},{"code":"09","name":"其他或待分类器质性精神障碍","block":"0 器质性精神障碍","blockEn":"Organic mental disorders","criteria":[{"section":"说明","text":"躯体疾病所致精神障碍；F09 待分类器质性痴呆\n（1）以上未分类的其他器质性精神障碍，为指明原发疾病应加相关ICD-10 编码；\n（2）器质性精神障碍无法确定为哪一型时也用本编码。"}]},{"code":"10","name":"精精神活性物质所致精神障碍","block":"1 精精神活性物质或非成瘾物质所致精神障碍","blockEn":"Mental disorders due to psychoactive substances or non-addictive substances","criteria":[{"section":"说明","text":"精神活物质是指来自体外，可影响精神活动，并可导致成瘾的物质。常见的精神活性\n物质有酒类、阿片类、大麻、催眠药、抗焦虑药、麻醉药、兴奋剂、致幻剂和烟草等。精\n精神活性物质可由医生处方不当或个人擅自反复使用导致依赖综合征和其他精神障碍，如中\n毒、戒断综合征、精神病性症状、情感障碍，及残留性或迟发性精神障碍等。"},{"section":"症状标准","text":"1  有精精神活性物质进入体内的证据，并有理由推断精神障碍系该物质所致；\n2  出现躯体或心理症状，如中毒、依赖综合征、戒断综合征、精神病性症状，及情感\n障碍、残留性或迟发性精神障碍等。"},{"section":"严重标准","text":"社会功能受损。"},{"section":"病程标准","text":"除残留性或迟发性精神障碍之外，精神障碍发生在精精神活性物质直接效应所\n能达到的合理期限之内。"},{"section":"排除标准","text":"排除精精神活性物质诱发的其他精神障碍。"},{"section":"说明","text":"如应用多种精精神活性物质，鼓励作出一种以上精精神活性物质所致精神障碍的诊断，\n并分别编码。"}]},{"code":"10.1","name":"酒精所致精神障碍","block":"1 精精神活性物质或非成瘾物质所致精神障碍","blockEn":"Mental disorders due to psychoactive substances or non-addictive substances","criteria":[{"section":"说明","text":"符合精精神活性物质所致精神障碍诊断标准，有理由推断精神障碍系酒精所致。"}]},{"code":"10.2","name":"阿片类物质所致精神障碍","block":"1 精精神活性物质或非成瘾物质所致精神障碍","blockEn":"Mental disorders due to psychoactive substances or non-addictive substances","criteria":[{"section":"说明","text":"符合精精神活性物质所致精神障碍诊断标准，有理由推断精神障碍系阿片类物质（如阿\n片、海洛因、杜冷丁等）所致。"}]},{"code":"10.3","name":"大麻类物质所致精神障碍","block":"1 精精神活性物质或非成瘾物质所致精神障碍","blockEn":"Mental disorders due to psychoactive substances or non-addictive substances","criteria":[{"section":"说明","text":"符合精精神活性物质所致精神障碍诊断标准，有理由推断精神障碍系大麻类物质所致。"}]},{"code":"10.4","name":"镇静催眠药或抗焦虑药所致精神障碍","block":"1 精精神活性物质或非成瘾物质所致精神障碍","blockEn":"Mental disorders due to psychoactive substances or non-addictive substances","criteria":[{"section":"说明","text":"符合精精神活性物质所致精神障碍诊断标准，有理由推断精神障碍系镇静、催眠、镇痛、\n抗焦虑和麻醉等中枢神经抑制剂（阿片类物质除外）所致。"}]},{"code":"10.5","name":"兴奋剂所致精神障碍","block":"1 精精神活性物质或非成瘾物质所致精神障碍","blockEn":"Mental disorders due to psychoactive substances or non-addictive substances","criteria":[{"section":"说明","text":"符合精精神活性物质所致精神障碍诊断标准，有理由推断精神障碍系兴奋剂（如苯丙胺、\n甲基苯丙胺、咖啡因、利他林、可卡因等）所致。"}]},{"code":"10.6","name":"致幻剂所致精神障碍","block":"1 精精神活性物质或非成瘾物质所致精神障碍","blockEn":"Mental disorders due to psychoactive substances or non-addictive substances","criteria":[{"section":"说明","text":"符合精精神活性物质所致精神障碍诊断标准，有理由推断精神障碍系致幻剂（如LSD）\n所致。"}]},{"code":"10.7","name":"烟草所致精神障碍","block":"1 精精神活性物质或非成瘾物质所致精神障碍","blockEn":"Mental disorders due to psychoactive substances or non-addictive substances","criteria":[{"section":"说明","text":"符合精精神活性物质所致精神障碍的诊断标准，有理由推断精神障碍（主要是依赖综合\n征和戒断综合征）系由烟草所致。"}]},{"code":"10.8","name":"挥发性溶剂所致精神障碍","block":"1 精精神活性物质或非成瘾物质所致精神障碍","blockEn":"Mental disorders due to psychoactive substances or non-addictive substances","criteria":[{"section":"说明","text":"符合精精神活性物质所致精神障碍诊断标准，有理由推断精神障碍系吸入汽油等挥发性\n物质所致。"}]},{"code":"10.9","name":"其他或待分类的精精精神活性物质所致精神障碍","block":"1 精精神活性物质或非成瘾物质所致精神障碍","blockEn":"Mental disorders due to psychoactive substances or non-addictive substances","criteria":[{"section":"说明","text":"精神障碍和行为障碍]\n符合精精神活性物质所致精神障碍诊断标准，有理由推断精神障碍系上述以外的其他或\n待分类的精精神活性物质所致。"}]},{"code":"11","name":"非成瘾物质所致精神障碍","block":"1 精精神活性物质或非成瘾物质所致精神障碍","blockEn":"Mental disorders due to psychoactive substances or non-addictive substances","criteria":[{"section":"说明","text":"指来自体外的某些物质,虽不产生心理或躯体性成瘾,但可影响个人精神状态,如产生\n摄入过量所致的中毒症状(过去称为中毒性精神障碍)或突然停用所致的停药综合征(如反\n跳现象)。"},{"section":"症状标准","text":"有非成瘾物质进入体内的证据，并有理由推断精神障碍系该物质所致。由此\n引发心理或躯体症状，如中毒、智能障碍、精神病性症状、情感症状、神经症样症状、或\n人格改变等。"},{"section":"严重标准","text":"社会功能受损。"},{"section":"病程标准","text":"除残留性或迟发性精神障碍之外，精神障碍发生在非成瘾物质直接效应所能\n达到的合理期限之内。"},{"section":"排除标准","text":"排除精精神活性物质所致精神障碍和器质性精神障碍。"}]},{"code":"11.1","name":"非成瘾药物所致精神障碍","block":"1 精精神活性物质或非成瘾物质所致精神障碍","blockEn":"Mental disorders due to psychoactive substances or non-addictive substances","criteria":[{"section":"说明","text":"符合非成瘾物质所致精神障碍诊断标准，有理由推断精神障碍系非成瘾物质（如激素、\n异烟肼等）所致。应标明具体药物，如：①抗抑郁剂（如三环类、四环类、及单胺氧化酶\n抑制剂）[F55.0]；②缓泻剂[F55.1]；③止痛药（没指定为精精神活性物质的，如阿斯匹林，\n非那西丁）[F55.2]；④制酸药[F55.3]；⑤维生素类[F55.4]；⑥类固醇或激素[F55.5]；⑦特\n殊的草药或民间验方[F55.6]等。"}]},{"code":"11.2","name":"一氧化碳所致精神障碍","block":"1 精精神活性物质或非成瘾物质所致精神障碍","blockEn":"Mental disorders due to psychoactive substances or non-addictive substances","criteria":[{"section":"说明","text":"符合非成瘾物质所致精神障碍诊断标准，有理由推断精神障碍系一氧化碳所致。"}]},{"code":"11.3","name":"有机化合物所致精神障碍","block":"1 精精神活性物质或非成瘾物质所致精神障碍","blockEn":"Mental disorders due to psychoactive substances or non-addictive substances","criteria":[{"section":"说明","text":"符合非成瘾物质所致精神障碍诊断标准，有理由推断精神障碍系有机化合物（如苯、\n有机磷等）所致。应标明具体有机化合物，如：①有机磷；②苯等。"}]},{"code":"11.4","name":"重金属所致精神障碍","block":"1 精精神活性物质或非成瘾物质所致精神障碍","blockEn":"Mental disorders due to psychoactive substances or non-addictive substances","criteria":[{"section":"说明","text":"符合非成瘾物质所致精神障碍诊断标准，有理由推断精神障碍系重金属（如铅、汞等）\n所致。应标明具体重金属，如：①铅；②汞等。"}]},{"code":"11.5","name":"食物所致精神障碍","block":"1 精精神活性物质或非成瘾物质所致精神障碍","blockEn":"Mental disorders due to psychoactive substances or non-addictive substances","criteria":[{"section":"说明","text":"符合非成瘾物质所致精神障碍诊断标准，有理由推断精神障碍系食物（如蕈类）所致。"}]},{"code":"11.9","name":"其他待分类的非成瘾物质所致精神障碍","block":"1 精精神活性物质或非成瘾物质所致精神障碍","blockEn":"Mental disorders due to psychoactive substances or non-addictive substances","criteria":[{"section":"说明","text":"待分类的不产生依赖的物质滥用]\n符合非成瘾物质所致精神障碍诊断标准，有理由推断精神障碍系多种或上述以外的其\n他或待分类的非成瘾物质所致。应标明多种或上述以外的其他或待分类的非成瘾物质如二\n氧化碳等。"}]},{"code":"20","name":"精神分裂症（分裂症）","block":"2 精神分裂症（分裂症）和其他精神病性障碍","blockEn":"Schizophrenia and other psychotic disorders","criteria":[{"section":"说明","text":"本症是一组病因未明的精神病，多起病于青壮年，常缓慢起病，具有思维、情感、行\n为等多方面障碍，及精神活动不协调。通常意识清晰，智能尚好，有的病人在疾病过程中\n可出现认知功能损害，自然病程多迁延，呈反复加重或恶化，但部分病人可保持痊愈或基\n本状态。"},{"section":"症状标准","text":"至少有下列2 项并非继发于意识障碍、智能障碍、情感高涨或低落，单纯型\n分裂症加规定：\n1  反复出现的言语性幻听；\n2  明显的思维松弛、思维破裂、言语不连贯，或思维贫乏或思维内容贫乏；\n3  思想被插入、被撤走、被播散、思维中断，或强制性思维；\n4  被动、被控制，或被洞悉体验；\n5  原发性妄想（包括妄想知觉，妄想心境）或其他荒谬的妄想；\n6  思维逻辑倒错、病理性象征性思维，或语词新作；\n7  情感倒错，或明显的情感淡漠；\n8  紧张综合征、怪异行为，或愚蠢行为；\n9  明显的意志减退或缺乏。"},{"section":"严重标准","text":"自知力障碍，并有社会功能严重受损或无法进行有效交谈。"},{"section":"病程标准","text":"1  符合病症标准和严重标准至少已持续1 个月，单纯型另有规定。\n2  若同时符合分裂症和情感性精神障碍的症状标准，当情感症状减轻到不能满足情感\n性精神障碍症状标准时，分裂症状需继续满足分裂症的症状标准至少2 周以上，方可诊断\n为分裂症。"},{"section":"排除标准","text":"排除器质性精神障碍，及精精神活性物质和非成瘾物质所致精神障碍。尚未缓\n解的分裂症病人，若又罹患本项中前述两类疾病，应并列诊断。"}]},{"code":"20.1","name":"偏执型分裂症","block":"2 精神分裂症（分裂症）和其他精神病性障碍","blockEn":"Schizophrenia and other psychotic disorders","criteria":[{"section":"说明","text":"符合分裂症诊断标准，以妄想为主，常伴有幻觉，以听幻觉较多见。"}]},{"code":"20.2","name":"青春型（瓦解型）分裂症","block":"2 精神分裂症（分裂症）和其他精神病性障碍","blockEn":"Schizophrenia and other psychotic disorders","criteria":[{"section":"说明","text":"符合分裂症诊断标准，常在青年期起病，以思维、情感、行为障碍或紊乱为主。例如\n明显的思维松弛、思维破裂、情感倒错、行为怪异。"}]},{"code":"20.3","name":"紧张型分裂症","block":"2 精神分裂症（分裂症）和其他精神病性障碍","blockEn":"Schizophrenia and other psychotic disorders","criteria":[{"section":"说明","text":"符合分裂症诊断标准，以紧张综合征为主，其中以紧张性木僵较常见。"}]},{"code":"20.4","name":"脑外伤所致精神障碍","block":"2 精神分裂症（分裂症）和其他精神病性障碍","blockEn":"Schizophrenia and other psychotic disorders","criteria":[{"section":"说明","text":"由各种脑外伤导致的精神障碍和后遗综合征，诊断需标明脑外伤或后遗综合征类型，"}]},{"code":"20.5","name":"未定型分裂症","block":"2 精神分裂症（分裂症）和其他精神病性障碍","blockEn":"Schizophrenia and other psychotic disorders","criteria":[{"section":"诊断标准","text":"1  符合分裂症诊断标准，有明显阳性病症状；\n2  不符合上述亚型的诊断标准，或为偏执型、青春型，或紧张型的混合形式。"},{"section":"说明","text":"本型又名混合型或未分型。"}]},{"code":"20.9","name":"其他型或待分类的分裂症","block":"2 精神分裂症（分裂症）和其他精神病性障碍","blockEn":"Schizophrenia and other psychotic disorders","criteria":[{"section":"说明","text":"符合分裂症诊断标准，不符合上述各型的诊断标准，如：20.91 儿童分裂症、20.92 晚\n发性分裂症等。"}]},{"code":"21","name":"偏执性精神障碍","block":"2 精神分裂症（分裂症）和其他精神病性障碍","blockEn":"Schizophrenia and other psychotic disorders","criteria":[{"section":"说明","text":"偏执性精神障碍指一组以系统妄想为主要症状，而病因未明的精神障碍，若有幻觉则\n历时短暂且不突出。在不涉及妄想的情况下，无明显的其他心理方面异常。30 岁以后起\n病者较多。"},{"section":"症状标准","text":"以系统妄想为主要症状，内容较固定，并有一定的现实性，不经了解，难辨\n真伪。主要表现为被害、嫉妒、夸大、疑病，或钟情等内容。"},{"section":"严重标准","text":"社会功能严重受损和自知力障碍。"},{"section":"病程标准","text":"符合症状标准和严重标准至少已持续3 个月。"},{"section":"排除标准","text":"排除器质性精神障碍、精精神活性物质和非成瘾物质所致精神障碍、分裂症，\n或情感性精神障碍。"},{"section":"说明","text":"CCMD-3 中偏执狂（妄想狂）与偏执状态（类偏狂）已合并为一个诊断，使用同\n一编码，这与ICD-10 和DSM-4 一致。"}]},{"code":"22","name":"急性短暂性精神病","block":"2 精神分裂症（分裂症）和其他精神病性障碍","blockEn":"Schizophrenia and other psychotic disorders","criteria":[{"section":"说明","text":"急性短暂性精神病指一组起病急骤，以精神病性症状为主的短暂精神障碍，多数病人\n能缓解或基本缓解。"},{"section":"症状标准","text":"精神病性症状，至少需符合下列1 项：\n1  片断妄想，或多种妄想；\n2  片断幻觉，或多种幻觉；\n3  言语紊乱；\n4  行为紧张或紧张症。"},{"section":"严重标准","text":"日常生活、社会功能严重受损或给别人造成危险或不良后果。"},{"section":"病程标准","text":"符合症状标准和严重标准至少已数小时至1 个月，或另有规定。"},{"section":"排除标准","text":"排除器质性精神障碍、精精神活性物质和非成瘾物质所致精神障碍、分裂症，\n或情感性精神障碍。"}]},{"code":"22.1","name":"分裂样精神病","block":"2 精神分裂症（分裂症）和其他精神病性障碍","blockEn":"Schizophrenia and other psychotic disorders","criteria":[{"section":"说明","text":"符合分裂症和各项诊断标准，但符合症状标准的持续时间不到1 个月。"}]},{"code":"22.2","name":"旅途性精神病","block":"2 精神分裂症（分裂症）和其他精神病性障碍","blockEn":"Schizophrenia and other psychotic disorders","criteria":[{"section":"说明","text":"指一种病前存在明显的综合性应激因素（如精神刺激、过度疲劳、过分拥挤、慢性缺\n氧、睡眠缺乏、营养水分缺乏等），在旅行途中（铁路、公路、水路，或空中旅行等，）急\n性起病的精神障碍主要表现为意识障碍，片断的妄想、幻觉，或行为紊乱。病程短暂，停\n止旅行与充分休息后，数小时至1 周内可自行缓解。诊断应排除癔症和旅途中发生的其他\n精神障碍，如分裂症、情感性精神障碍等。"},{"section":"症状标准","text":"在旅行途中（铁路、公路、水路，或空中旅行等），急性起病。病前有明显精\n神应激、过度疲劳、过分拥挤、慢性缺氧、睡眠缺乏、营养水分缺乏等综合因素作用。常\n可出现意识障碍，片断的妄想、幻觉，或行为紊乱。"},{"section":"严重标准","text":"社会功能严重受损，或给别人造成危险或不良后果。"},{"section":"病程标准","text":"病程短暂，停止旅行与充分休息后，数小时至1 周内自行缓解。"},{"section":"排除标准","text":"排除癔症和旅途中发生的其他精神障碍，如分裂症、情感性精神障碍等。"}]},{"code":"22.3","name":"妄想阵发（急性妄想发作）","block":"2 精神分裂症（分裂症）和其他精神病性障碍","blockEn":"Schizophrenia and other psychotic disorders","criteria":[{"section":"说明","text":"一般无明显发病诱因，常突然急性起病，多在1 周内症状达到高峰，以短暂妄想为主，\n可有情感和行为障碍。多见于青壮年，不发生于儿童，50 岁以后罕见。"},{"section":"诊断标准","text":"1  符合急性短暂性精神病的症状标准。以突然产生多种结构松散，变换不定的妄想为\n主，如被害、夸大、嫉妒，或宗教妄想。可伴有恍惚、错觉、短暂幻觉、人格解体，或运\n动增多或减少；\n2  病程短暂，但部分病例病程可长达3 个月；\n3  排除反应性精神病、精精神活性物质和非成瘾物质所致精神障碍，或有持续性幻觉与\n特征性思维障碍的分裂样精神病。"}]},{"code":"22.9","name":"其他或待分类的急性短暂性精神病","block":"2 精神分裂症（分裂症）和其他精神病性障碍","blockEn":"Schizophrenia and other psychotic disorders","criteria":[{"section":"说明","text":"障碍]"}]},{"code":"23","name":"感应性精神病","block":"2 精神分裂症（分裂症）和其他精神病性障碍","blockEn":"Schizophrenia and other psychotic disorders","criteria":[{"section":"说明","text":"以系统妄想为突出症状的精神障碍，往往发生于同一环境或家庭中两个关系极为密切\n的亲属或挚友中（如母女、姐妹、夫妻、师生等），其妄想内容相似。"},{"section":"症状标准","text":"1  起病前已有一位长期相处、关系密切的亲人患有妄想症状的精神病，继而病人出现\n精神病，且妄想内容相似；\n2  病人生活在相对封闭的家庭中，外界交往少。被感应病人与原发病人有思想情感上\n的共鸣，感应者处权威地位，被感应者具有驯服，依赖等人格特点；\n3  以妄想为主要临床相。"},{"section":"严重标准","text":"社会功能严重受损。"},{"section":"病程标准","text":"病程有迁延趋势，但被感应者与原发病者隔离后，被感应者可缓解。"},{"section":"排除标准","text":"排除偶然同时或先后发病，但彼此没有明显影响的病例。"},{"section":"说明","text":"偶尔一位存在妄想症状的精神病人，可导致多个与之长期相处、关系密切的亲人\n发生类似病症。"}]},{"code":"24","name":"分裂情感性精神病","block":"2 精神分裂症（分裂症）和其他精神病性障碍","blockEn":"Schizophrenia and other psychotic disorders","criteria":[{"section":"说明","text":"指一组分裂症状和情感症状同时存在又同样突出，常有反复发作的精神病。分裂症状\n为妄想、幻觉，及思维障碍等阳性精神病性症状，情感性症状为躁狂发作或抑郁发作症状。"},{"section":"症状标准","text":"同时符合分裂症和情感性精神障碍躁狂或抑郁发作的症状标准。"},{"section":"严重标准","text":"社会功能严重受损和自知力不全或缺乏。"},{"section":"病程标准","text":"符合症状标准的分裂症状与情感症状在整个病程中同时存在至少2 周以上，\n并且出现与消失的时间较接近。"},{"section":"排除标准","text":"排除器质性精神障碍、精精神活性物质和非成瘾物质所致精神障碍、分裂症，\n或情感性精神障碍。"},{"section":"说明","text":"如在不同发作中分别表现以分裂性症状或情感性症状为主要临床相，仍按每次发\n作的主要临床相作出各自的诊断。\n分裂情感性精神病分型："}]},{"code":"24.1","name":"分裂情感性精神病，躁狂型","block":"2 精神分裂症（分裂症）和其他精神病性障碍","blockEn":"Schizophrenia and other psychotic disorders","criteria":[]},{"code":"24.2","name":"分裂情感性精神病，抑郁型","block":"2 精神分裂症（分裂症）和其他精神病性障碍","blockEn":"Schizophrenia and other psychotic disorders","criteria":[]},{"code":"24.3","name":"分裂情感性精神病，混合型","block":"2 精神分裂症（分裂症）和其他精神病性障碍","blockEn":"Schizophrenia and other psychotic disorders","criteria":[]},{"code":"29","name":"其他或待分类的精神病性障碍","block":"2 精神分裂症（分裂症）和其他精神病性障碍","blockEn":"Schizophrenia and other psychotic disorders","criteria":[]},{"code":"29.1","name":"周期性精神病","block":"2 精神分裂症（分裂症）和其他精神病性障碍","blockEn":"Schizophrenia and other psychotic disorders","criteria":[{"section":"说明","text":"这是一组急性起病，反复发作，症状相仿，以内分泌失调与自主神经症状，以及思维、\n情感、行为紊乱为主的精神障碍，病程短暂，抗精神病药物疗效不显著，多见于青少年女\n性。如果常与月经周期相联系，则称月经周期性精神病。"},{"section":"症状标准","text":"1  内分泌失调与自主神经症状，并至少有下列1 项：\n①非协调性精神运动性兴奋，少数为运动抑郁；\n②伴有轻度意识障碍的行为紊乱；\n③片断的幻觉、妄想与言语紊乱；\n④明显的情感高涨或低落。\n2  每次发作的症状几乎相同。"},{"section":"严重标准","text":"发作期社会功能严重受损，间歇期完全缓解，恢复病前状态。"},{"section":"病程标准","text":"急性起病，每次发作不超过2 周；在6 个月内至少发作3 次。"},{"section":"排除标准","text":"排除快速循环型情感性精神障碍、癔症性精神病和分裂样精神病。\n心境障碍（情感性精神障碍）[F30-F39]\n心境障碍（情感性精神障碍）以明显而持久的心境高涨或低落为主的一组精神障碍，\n并有相应的思维和行为改变。可有精神病性症状，如幻觉妄想。大多数病人有反复发作的\n倾向，每次发作多可缓解，部分可有残留症状或转为慢性。"}]},{"code":"30","name":"躁狂发作","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"躁狂发作以心境高涨为主，与其处境不相称，可以从高兴愉快到欣喜若狂，某些病例\n仅以易激惹为主。病性轻者社会功能无损害或仅有轻度损害，严重者可出现幻觉、妄想等\n精神病性症状。"},{"section":"症状标准","text":"以情绪高涨或易激惹为主，并至少有下列3 项（若仅为易激惹，至少需4 项 ）：\n1  注意力不集中或随境转移；\n2  语量增多；\n3  思维奔逸（语速增快、言语迫促等）、联想加快或意念飘忽的体验；\n4  自我评价过高或夸大；\n5  精力充沛、不感疲乏、活动增多、难以安静，或不断改变计划和活动；\n6  鲁莽行为（如挥霍、不负责任，或不计后果的行为等）\n7  睡眠需要减少；\n8  性欲亢进。"},{"section":"严重标准","text":"严重损害社会功能，或给别人造成危险或不良后果。"},{"section":"病程标准","text":"1  符合症状标准和严重标准至少已持续1 周；\n2  可存在某些分裂性症状，但不符合分裂症的诊断标准。若同时符合分裂症的症状标\n准，在分裂症状缓解后，满足躁狂发作标准至少1 周。"},{"section":"排除标准","text":"排除器质性精神障碍，或精精神活性物质和非成瘾物质所致躁狂。"},{"section":"说明","text":"本躁狂发作标准仅适用于单次发作的诊断。"}]},{"code":"30.1","name":"轻性躁狂症(轻躁狂)","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"除了社会功能无损害或仅轻度损害外，发作符合30 躁狂发作标准。"}]},{"code":"30.2","name":"无精神病性症状的躁狂症","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"除了在30 躁狂发作的症状标准中，增加“无幻觉、妄想，或紧张综合征等精神病性症\n状“之其，其余均符合该标准。"}]},{"code":"30.3","name":"有精神病性症状的躁狂症","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"除了在30 躁狂发作的症状标准中，增加“有幻觉、妄想，或紧张综合征等精神病性症\n状”之外，其余均符合该标准。"}]},{"code":"30.4","name":"复发性躁狂症","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"诊断标准","text":"1  目前发作符合上述某一型躁狂标准，并在间隔至少2 个月前。有过1 次发作符合上\n述某一型躁狂标准；\n2  从未有抑郁障碍符合任何一型抑郁、双相情感障碍，或环性情感障碍标准；\n3  排除器质性精神障碍，或精精神活性物质和非成瘾物质所致的躁狂发作。"}]},{"code":"30.9","name":"其他或待分类的躁狂","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[]},{"code":"30.41","name":"复发性躁狂症，目前为轻躁狂","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"符合30.4 复发性躁狂的诊断标准，目前发作符合30.1 轻躁狂标准。"}]},{"code":"30.42","name":"复发性躁狂症目，前为无精神病性症状的躁狂","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"符合30.4 复发性躁狂的诊断标准，目前发作符合30.2 无精神病性症状的躁狂标准。"}]},{"code":"30.43","name":"复发性躁狂症，目前为有精神病性症状的躁狂","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"符合30.4 复发性躁狂的诊断标准，目前发作符合30.3 有精神病性症状的躁狂标准。"}]},{"code":"31","name":"双相障碍","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"目前发作符合某一型躁狂或抑郁标准，以前有相反的临床相或混合性发作，如在躁狂\n发作后又有抑郁发作或混合性发作。"}]},{"code":"31.1","name":"双相障碍，目前为轻躁狂","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"目前发作符合30.1 轻躁狂标准，以前至少有1 次发作符合某一型抑郁标准。"}]},{"code":"31.2","name":"双相障碍，目前为无精神病性症状的躁狂","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"目前发作符合30.2 无精神病性症状的躁狂标准，以前至少有1 次发作符合某一型抑\n郁标准。"}]},{"code":"31.3","name":"双相障碍，目前为有精神病性症状的躁狂","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"目前发作符合30.3 有精神病性症状的躁狂标准，以前至少有1 次发作符合某一型抑\n郁标准。"}]},{"code":"31.4","name":"双相障碍，目前为轻抑郁","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"目前发作符合32.1 轻抑郁标准，以前至少有1 次发作符合某一型躁狂标准。"}]},{"code":"31.5","name":"双相障碍，目前为无精神病性症状的抑郁","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"目前发作符合32.2 无精神病性症状的抑郁标准，以前至少有1 次发作符合某一型躁\n狂标准。"}]},{"code":"31.6","name":"双相障碍，目前为有精神病性症状的抑郁","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"目前发作符合32.3 有精神病性症状的抑郁标准，以前至少有1 次发作符合某一型躁\n狂标准。"}]},{"code":"31.7","name":"双相障碍，目前为混合性发作","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"诊断标准","text":"1  目前发作以躁狂和抑郁症状混合或迅速交替（即在数小时内）为特征，至少持续2\n周躁狂和抑郁均很突出；\n2  以前至少有1 次作符合某一型抑郁标准或躁狂标准。"}]},{"code":"31.9","name":"其他或待分类的双相障碍","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[]},{"code":"31.91","name":"双相障碍，目前为快速循环发作","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"在过去12 个月中，至少有4 次情感障碍发作，每次发作符合30.1 轻躁狂或30 躁狂\n发作、32.1 轻抑郁或32 抑郁发作，或情感障碍的混合性发作标准 。"}]},{"code":"32","name":"抑郁发作","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"抑郁发作以心境低落为主，与其处境不相称，可以从闷闷不乐到悲痛欲绝，甚至发生\n木僵。严重者可出现幻觉、妄想等精神性症状。某些病例的焦虑与运动性激越很显著。"},{"section":"症状标准","text":"以心境低落为主，并至少有下列4 项：\n1  兴趣丧失、无愉快感；\n2  精力减退或疲乏感；\n3  精神运动性迟滞或激越；\n4  自我评价过低、自责，或有内疚感；\n5  联想困难或自觉思考能力下降；\n6  反复出现想死的念头或有自杀、自伤行为；\n7  睡眠障碍，如失眠、早醒，或睡眠过多；\n8  食欲降低或体重明显减轻；\n9  性欲减退 。"},{"section":"严重标准","text":"社会功能受损，给本人造成痛苦或不良后果。"},{"section":"病程标准","text":"1  符合症状标准和严重标准至少已持续2 周。\n2  可存在某些分裂性症状，但不符合分裂症的诊断。若同时符合分裂症的症状标准，\n在分裂症状缓解后，满足抑郁发作标准至少2 周。"},{"section":"排除标准","text":"排除器质性精神障碍或，精精神活性物质和非成瘾物质所致抑郁。"},{"section":"说明","text":"本抑郁发作标准仅适用于单次发作的诊断。"}]},{"code":"32.1","name":"轻性抑郁症（轻抑郁）","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"除了社会功能无损害或仅轻度损害外，发作符合32 抑郁发作的全部标准。"}]},{"code":"32.2","name":"无精神病性症状的抑郁症","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"除了在32 抑郁发作的症状标准中，增加：无幻觉、妄想，或紧张综合征等精神病性\n症状”之外，其余均符合该标准。"}]},{"code":"32.3","name":"有精神病性症状抑郁症","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"除了在32 抑郁发作的症状标准中，增加“有幻觉、妄想或紧张综合征等精神病性症状”\n之外，其余均符合该标准。"}]},{"code":"32.4","name":"复发性抑郁症","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"诊断标准","text":"1  目前发作符合某一型抑郁标准，并在间隔至少2 个月前，有过另1 次发作符合某一\n型抑郁标准；\n2  以前从未有躁狂符合任何一型躁狂、双相情感障碍，或环性情感障碍标准；\n3  排除器质性精神障碍，或精精神活性物质和非成瘾物质所致的抑郁发作。"}]},{"code":"32.9","name":"其他或待分类的抑郁症","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[]},{"code":"32.41","name":"复发性抑郁症，目前为轻抑郁","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"符合32.4 复发性抑郁的诊断标准，目前发作符合32.1 轻抑郁标准。"}]},{"code":"32.42","name":"复发性抑郁症，目前为无精神病性症状的抑郁","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"符合32.4 复发性抑郁的诊断标准，目前发作符合32.2 无精神病性症状的抑郁标准。"}]},{"code":"32.43","name":"复发性抑郁症，目前为有精神病性症状的抑郁","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"说明","text":"符合32.4 复发性抑郁的诊断标准，目前发作符合32.3 有精神病性症状的抑郁标准。"}]},{"code":"33","name":"持续性心境障碍","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[]},{"code":"33.1","name":"环性心境障碍","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"症状标准","text":"反复出现心境高涨或低落，但不符合躁狂或抑郁发作症状标准。"},{"section":"严重标准","text":"社会功能受损较轻。"},{"section":"病程标准","text":"符合症状标准和严重标准至少已2 年，但这2 年中，可有数月心境正常间歇\n期。[排除标准]\n1  心境变化并非躯体或精精神活性物质的直接后果，也非分裂症及其他精神病性障碍的\n附加症状；\n2  排除躁狂或抑郁发作，一旦符合个应标准即诊断为其他类型情感障碍。"}]},{"code":"33.2","name":"恶劣心境","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[{"section":"症状标准","text":"持续存在心境低落，但不符合任何一型抑郁的症状标准，同时无躁狂症状。"},{"section":"严重标准","text":"社会功能受损较轻，自知力完整或较完整。"},{"section":"病程标准","text":"符合症状标准和严重标准至少已2 年，在这2 年中，很少有持续2 个月的心\n境正常间歇期。"},{"section":"排除标准","text":"1  心境变化并非躯体病（如甲状腺机能亢进症），或精精神活性物质导致的直接后果，也\n非分裂症及其他精神病性障碍的附加症状。\n2  排除各型抑郁（包括慢性抑郁或环性情感障碍），一旦符合相应的其他类型情感障碍\n标准，则应作出相应的其他类型诊断；\n3  排除抑郁性人格障碍。"}]},{"code":"33.9","name":"其他或待分类的持续性心境障碍","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[]},{"code":"39","name":"其他或待分类的心境障碍","block":"3 心境障碍（情感性精神障碍）","blockEn":"Mood (affective) disorders","criteria":[]},{"code":"40","name":"癔症","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"癔症指一种以解离症状（部分或完全丧失对自我身份识别和对过去的记忆，CCMD-3\n称为癔症性精神症状）和转换症状（在遭遇无法解决的问题和冲突时产生的不快心情，以\n转化成躯体症状的方式出现，CCMD-3 称为癔症性躯体症状）为主的精神障碍，这些症状\n没有可证实的器质性病变基础。本障碍有癔症性人格基础，起病常受心理社会（环境）因\n素影响，除癔症性精神病或癔症性意识障碍有自知力障碍外，自知力基本完整，病程多反\n复迁延。常见于青春期和更年期，女性较多。"},{"section":"症状标准","text":"1  有心理社会因素作为诱因，并至少下列1 项综合征：\n①癔症性遗忘；\n②癔症性漫游；\n③癔症性多重人格；\n④癔症性精神病；\n⑤癔症性运动和感觉障碍；\n⑥其他癔症形式；\n2  没有可解释上述症状的躯体疾病。"},{"section":"严重标准","text":"社会功能受损。"},{"section":"病程标准","text":"起病与应激事件之间有明确联系，病程多反复迁延。"},{"section":"排除标准","text":"排除器质性精神障碍（如癫痫所致精神障碍）、诈病。"},{"section":"说明","text":"1  癫痫可并有癔症表现，此时应并列诊断；\n2  癔症性症状可见于分裂症和情感性精神障碍，假如有分裂症状或情感症状存在，应\n分别作出后两者的相应诊断。"}]},{"code":"40.1","name":"癔症性精神障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[]},{"code":"40.2","name":"癔症性躯体障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[]},{"code":"40.3","name":"混合性癔症躯体—精神障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"上述解离障碍或转换障碍的任何混合形式。"}]},{"code":"40.9","name":"其他或待分类癔症","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"符合癔症的诊断标准，但不符合上述所列各癔症亚型标准的癔症。\n40．91Ganser 综合征[F44.80Ganser 综合征]"}]},{"code":"40.11","name":"癔症性遗忘","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"诊断标准","text":"1  符合癔症诊断标准；\n2  对曾经是或仍然是创伤性或应激性事件有部分或完全遗忘；\n排除器质性遗忘，如头部外伤后的遗忘和意识障碍（中毒、癫痫发作，或其他急性器质\n性障碍）恢复后的遗忘。"}]},{"code":"40.12","name":"癔症性漫游","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"诊断标准","text":"1  符合癔症诊断标准；\n2  在觉醒状态，作无计划和无目的漫游；漫游中能保持基本的自我照顾，以及与陌生\n人简单交往（如搭车，问路），与其不深入的短暂接触看不出有精神异常；\n3  有自我身份识别障碍，但不是癔症性多重人格；\n4  事后有遗忘；\n5  开始和结束都是突然的。"}]},{"code":"40.13","name":"癔症性身份识别障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"诊断标准","text":"1  符合癔症诊断标准；以自我身份识别障碍为主，丧失自我同一感，有双重人格或多\n重人格；\n2  对周围环境缺乏觉察，周围意识狭窄或对外界刺激异乎寻常的注意狭窄和选择性注\n意，并与病人改变了的身份相联系；\n3  上述症状必须是非己所欲，发生在宗教或文化背景认可情境中的类似状态之外或系\n其延伸；\n4  无幻觉、妄想等精神病性症状；\n5  排除分裂症用其相关障碍、情感性精神障碍。"}]},{"code":"40.14","name":"癔症性精神病","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"症状标准","text":"1  符合癔症诊断标准；\n2  反复出现的以幻想性生活情节为内容的片断幻觉或妄想、意识朦胧、表演性矫饰动\n作，或幼稚与混乱的行为，或木僵为主。"},{"section":"严重标准","text":"日常生活和社会功能受损，或自知力障碍，对疾病泰然漠视。"},{"section":"病程标准","text":"符合症状标准和严重标准至少已1 周，其中可有短暂间歇期。"},{"section":"排除标准","text":"排除分裂症或相关障碍、情感性精神障碍。"}]},{"code":"40.21","name":"癔症性运动性障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"诊断标准","text":"1  符合癔症的诊断标准，有心理社会因素作为诱因；\n2  有躯体运动不能障碍，如肢体瘫痪、站立不能，或步行不能；\n3  临床表现缺乏神经解剖生理基础；\n4  排除器质性疾病。"}]},{"code":"40.22","name":"癔症性抽搐发作","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"符合癔症的诊断标准和突然和出乎意料的抽搐发作，类似于癫痫发作的某种形式，但\n并无意识丧失、咬舌、严重摔伤，或小便失禁。应注意与癫痫发作的同病情况相鉴别。"}]},{"code":"40.23","name":"癔症性感觉障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"诊断标准","text":"1  符合癔症的诊断标准和有心理社会因素作为诱因；\n2  有躯体感觉障碍，如失、音失明、耳聋，或部分或整个躯体的某种或所有正常皮肤\n感觉的部分或全部丧失（应标明触觉、针刺觉、震动觉、热觉、冷觉等）；\n3  临床表现缺乏神经解剖生理基础和根据排除器质性疾病。"}]},{"code":"40.92","name":"见于童年和青少年的短暂的癔症性障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"换）性障碍]"}]},{"code":"40.141","name":"癔症性附体","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"符合癔症性精神病的诊断标准和以神怪或死者的亡灵等附体的自我身份识别障碍为\n主，因此取代了自己的身份，可达妄想程度。"}]},{"code":"40.142","name":"癔症性木僵","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"诊断标准","text":"1  符合癔症性精神病的诊断标准；\n2  以大僵为主。"}]},{"code":"40.1411","name":"与文化相关的癔症性附体障碍（与文化相关的癔症性附体障碍）","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"解离（转换）障碍]\n是一种在浓重的宗教或迷信背景下，由明显心理社会因素作为发病诱因的与文化相关\n的癔症。临床表现以神鬼、灵魂附体为主，病人常有癔症性格，有的已有过癔症发作史。\n应排除由巫师、巫医等通过祈祷、祭奠等仪式活动，自我诱导出现的附体状态。"},{"section":"诊断标准","text":"1  符合癔症性附体障碍的诊断标准和症状的产生及内容都与作为诱因的心因和宗教迷\n信有关，可达妄想程度，伴有情感爆发、哭笑无常、暗示性明显增高，或癔症性双重人格\n或多重人格等癔症症状；\n2  有部分的或完全的选择性遗忘，可伴有虚构；\n3  症状突然发生和中止，持续时间短暂。"}]},{"code":"41","name":"应激相关障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"指一组主要由心理、社会（环境）因素引起异常心理反应，导致的精神障碍，也称反\n应性精神障碍。决定本组精神障碍的发生、发展、病程，及临床表现的因素有：\n1  生活事件和生活处境，如剧烈的超强精神创伤或生活事件，或持续困难处境，均\n可成为直接病因；\n2  社会文化背景；\n3  人格特点、教育程度、智力水平，及生活态度和信念等；\n4  不包括癔症、神经症、心理因素所致生理障碍，及各种非心因性精神病性障碍。"}]},{"code":"41.1","name":"急性应激障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"以急剧\\严重的精神打击作为直接原因.在受刺激后立刻(1 小时之内)发病。表现有强烈\n恐惧体验的精神运动性兴奋。行为有一定的盲目性；或者为精神运动性抑制，甚至木僵。\n如果应激源被消除，症状往往历时短暂，预后良好，缓解完全。"},{"section":"症状标准","text":"以异乎寻常的和严重的精神刺激为原因，并至少有下列1 项：\n1  有强烈恐惧体验的精神运动性兴奋，行为有一家盲目性；\n2  有情感迟钝的精神运动性抑制（如反应性木僵），可有轻度意识模糊。"},{"section":"严重标准","text":"社会功能严重受损。"},{"section":"病程标准","text":"在受刺激后若干分钟至若干浊时发病，病程短暂，一般持续数浊时至1 周，\n通常在1 月内缓解。"},{"section":"排除标准","text":"排除癔症、器质性精神障碍、非成瘾物质所致精神障碍，及抑郁症。"}]},{"code":"41.2","name":"创伤后应激障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"由异乎寻常的威胁性或灾难性心理创伤，导致出现和长期持续的精神障碍。主要表现：\n1  反复发生闯入性的创伤性体验重现（病理性重现）、梦境，或因面临与刺激相似或有\n关的境遇，而感到痛苦和不由自主地反复回想；\n2  持续的警觉性增高；\n3  持续的回避；\n4  对创伤性经历的选择性遗忘；\n5  对未来失去信心。少数病人可有人格改变或有神经症病史等附加因素，从而降低了\n对应激原的应对能力或加重疾病过程。精神障碍延迟发生，在遭受创伤后数日甚至数月后\n才出现，病程可长达数年。"},{"section":"症状标准","text":"1  遭受对每个人来说都是异乎寻常的创伤性事件或处境（如天灾人祸）；\n2  反复重现创伤性体验（病理性重现），并至少有下列1 项：\n①不由自主地回想受打击的经历；\n②反复出现有创伤性内容的恶梦；\n③反复发生错觉、幻觉；\n④反复发生触景生情的精神痛苦，如目睹死者遗物、旧地重游，或周年目等情况下会\n感到异常痛苦和产生明显的生理反应，如心悸、出汗、面色苍白等；\n3  持续的警觉性增高，至少有下列1 项：\n①入睡困难或睡眠不深；\n②易激惹；\n③集中注意困难；\n④过分地担惊受怕；\n4  对与刺激相似或有关的情境的回避，至少有下列2 项：\n①极力不想有关创伤经历的人与事；\n②避免参加能引起痛苦回忆的活动，或避免到会引起痛苦回忆的地方；\n③不愿与人交往、对亲人变得冷淡；\n④兴趣爱好范围变窄，但对与创伤经历无关的某些活动仍有兴趣；\n⑤选择性遗忘；\n⑥对未来失去希望和信心。"},{"section":"严重标准","text":"社会功能受损。"},{"section":"病程标准","text":"精神障碍延迟发生（即在遭受创伤后数日至数月后，罕见延迟半年以上才发\n生），符合症状标准至少已3 个月。"},{"section":"排除标准","text":"排除情感性精神障碍、其他应激障碍、神经症、躯体形式障碍等。"}]},{"code":"41.3","name":"适应障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"因长期存在应激源或困难处境，加上病人有不一定的人格缺陷，产生以烦恼、抑郁等\n情感障碍为主，同时有适应不良的行为障碍或生理功能障碍，并使社会功能受损。病程往\n往较长，但一般不超过6 个月。通常在应激性事件或生活改变发生后1 个月内起病。随着\n事过增迁，刺激的消除或者以过调整形成了新的适度，精神障碍随之缓解。"},{"section":"症状标准","text":"1  有明显的生活事件为诱因，尤其是生活环境或社会地位的改变（如移民、出国、入\n伍、退休等）；\n2  有理由推断生活事件和人格基础对导致精神障碍均起着重要的作用；\n3  以抑郁、焦虑、害怕等情感症状为主，并至少有下列1 项：\n①适应不良的行为障碍，如退缩、不注意卫生、生活无规律等；\n②生理功能障碍，如睡眠不好、食欲不振等；\n4  存在见于情感性精神障碍（不包括妄想和幻觉）、神经症、应激障碍、躯体形式障碍，\n或品行障碍和各种症状，但不符合上述障碍的诊断标准。"},{"section":"严重标准","text":"社会功能受损。"},{"section":"病程标准","text":"精神障碍开始于心理社会刺激（但不是灾难性的或异乎寻常的）发生后1 个\n月内，符合症状标准至少已1 个月。应激因素消除后，症状持续一般不超过6 个月。"},{"section":"排除标准","text":"排除情感性精神障碍、应激障碍、神经症、躯体形式障碍，以及品行障碍等。"}]},{"code":"41.9","name":"其他或待分类的应激相关状态","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[]},{"code":"41.11","name":"急性应激性精神病（急性反应性精神病）","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"指一种急性应激障碍的亚型由强烈并持续一定时间的心理创伤性事件直接引起的精\n神病性障碍。 以妄想、严重情感障碍为主，症状内容与应激源密切相关，较易被人理解。\n急性或亚急性起病，经适当治疗，预后良好，恢复后精神正常，一般无人格缺陷。"},{"section":"症状标准","text":"1  病前遭受强烈精神刺激；\n2  以妄想或严重情感障碍为，主症状内容与精神刺激因素明显相，关而与个体素质因\n素关系较小。"},{"section":"严重标准","text":"社会功能和自知力严重受损。"},{"section":"病程标准","text":"病程短暂，仅个别病例超过1 个月。消除病因或改换环境（如解除拘禁）后\n症状迅速缓解。"},{"section":"排除标准","text":"排除癔症性精神病，以及其他非心因性精神病。"}]},{"code":"41.31","name":"短期抑郁反应","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"诊断标准","text":"1  符合适应障碍的诊断标准；\n2  抑郁为主的精神障碍开始于心理社会刺激（但不是灾难性的或异乎寻常的）发生后\n1 个月内，符合症状标准尚不足1 个月。"}]},{"code":"41.32","name":"中期抑郁反应","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"诊断标准","text":"1  符合适应障碍的诊断标准；\n2  抑郁为主的精神障碍开始于心理社会刺激但不是灾难性的或异乎寻常的）发生后1\n个月内，符合症状标准至少已1 个月，但持续不到半年。"}]},{"code":"41.33","name":"长期抑郁反应","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"诊断标准","text":"1  符合适应障碍的诊断标准；\n2  抑郁为主的精神障碍开始于心理社会刺激（但不是灾难性的或异乎寻常的）发生后\n1 个月内，符合症状标准至少已半年，但持续不到2 年。"}]},{"code":"41.34","name":"其他恶劣情绪为主和适应障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"诊断标准","text":"1  符合适应障碍的诊断标准；\n2  主要症状为除抑郁以外的其他恶劣情绪，如焦虑、烦恼、紧张及愤怒等；\n3  排除其他以焦虑或抑郁为主要症状的特定诊断。"}]},{"code":"41.35","name":"混合性焦虑反应","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"诊断标准","text":"1  符合适应障碍的诊断标准；\n2  主要症状为混合性焦虑抑郁情绪障碍。"}]},{"code":"41.36","name":"品行障碍为主的适应障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"诊断标准","text":"1  符合适应障碍的诊断标准；\n2  主要症状为品行障碍或行为问题，如悲伤反应导致的攻击或反社会行为等。"}]},{"code":"41.37","name":"心境和品行混合性障碍为主的适应障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"诊断标准","text":"1  符合适应障碍的诊断标准；\n2  主要症状为恶劣情绪与品行障碍的混合状态。"}]},{"code":"42","name":"与文化相关的精神障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"指一组与特定文化相关的综合征，其特点如下：\n1  被特定文化或亚文化范畴所理解接受；\n2  病因代表着和象征着这一文化的核心含义及行为模式；\n3  诊断依赖于特定的文化知识和概念；\n4  治疗的成功与否也取决于本文化的参与者。如我国的气功所致精神障碍，以及我国\n南部和马来西亚华人区域的恐缩症，均有以上特点。"}]},{"code":"42.1","name":"气功所致精神障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"气功是我国传统医学中健身治病的一种方法.通常做法是维持一定体位、姿势，或做\n某些动作，使注意集中于某处，沉思、默念、松驰，及调节呼吸等，可出现某些自我感觉\n和体验。气功所致精神障碍系指由于气功操练不当（如每日练习过多），处于气功态时间\n过长而不能收功的现象，表现为思维、情感，及行为障碍，并失去自我控制能力，俗称“走\n火入魔”。 [症状标准]\n1  由气功直接引起；\n2  症状与气功书刊或气功师所说的内容密切相关，通常只在做气功时出现，并在结束\n练功时迅即消失，而病人却持续出现或反复出现，无法自控；\n3  至少有下列1 项：\n①精神病性症状，如幻听、妄想等；\n②癔症样综合征；\n③神经症样综合征；"},{"section":"严重标准","text":"社会功能受损。"},{"section":"病程标准","text":"病程短暂，经脱离现场，中断练功，给予适当处理后很快恢复。"},{"section":"排除标准","text":"1  排除以类似表现作为治病手段，及获取财物或达到其他目的，或可随意自我诱发或\n自我终止者；\n2  排除其他精神障碍，尤其是癔症或严重应激障碍。"}]},{"code":"42.2","name":"巫术所致精神障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"诊断标准","text":"1  精神障碍由巫术诱发；\n2  症状与迷信巫术密切相关，以神鬼附体的身份障碍、片断的幻觉、错觉、妄想，或\n行为紊乱等为主；\n3  排除：\n①以巫术作为获取财物或达到其他目的者；\n②可随意自我诱发或自我终止者；\n③其他精神障碍。"}]},{"code":"42.3","name":"恐缩症(Koro)","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"是一种与文化相关的害怕生殖器、乳房，或身体某一部分缩入体内导致死亡的恐惧。\n焦虑发作。"},{"section":"诊断标准","text":"1  由明显的心理社会因素诱发；\n2  害怕生殖器、乳房，或身体某一部分会缩到身体里去而导致死亡。常采取某种预防\n（如系带牵引），同时有强烈的焦虑或恐惧情绪；\n急性起病，病程短暂。"}]},{"code":"42.9","name":"其他或待分类的与文化相关的精神障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[]},{"code":"43","name":"神经症","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"神经症是一组主要表现为焦虑、抑郁、恐惧、强迫、疑病症状，或神经衰弱症状的精\n神障碍。本障碍有一定人格基础，起病常受心理社会（环境）因素影响。症状没有可证实\n的器质性病变作基础，与病人的现实处境不相称，但病人对存在的症状感到痛苦和无能为\n力，自知力完整或基本完整，病程多迁延。各种神经症性症状或其组合可见于感染、中毒、\n内脏、内分泌或代谢和脑器质性疾病，称神经症样综合征。"},{"section":"症状标准","text":"至少有下列1 项：①恐惧；②强迫症状；③惊恐发作；④焦虑；⑤躯体形式\n症状；⑥躯体化症状；⑦疑病症状；⑧神经衰弱症状 。"},{"section":"严重标准","text":"社会功能受损或无法摆脱的精神痛苦，促使其主动求医。"},{"section":"病程标准","text":"符合症状标准至少已3 个月，惊恐障碍另有规定。"},{"section":"排除标准","text":"排除器质性精神障碍、精精神活性物质与非成瘾物质所致精神障碍、各种精神\n病性障碍，如精神分裂症、偏执性精神病，及心境障碍等。"}]},{"code":"43.1","name":"恐惧症（恐怖症）","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"是一种以过分和不合理地惧怕外界客体或处境为主神经症。病人明知没有必要，但仍\n不能防止恐惧发作，恐惧发作时往生育伴有显著的焦虑和自主神经症状。病人极力回避所\n害怕的客体或处境，或是带着畏惧去忍受。"},{"section":"诊断标准","text":"1  符合神经症的诊断标准；\n2  以恐惧为主，需符合以下4 项：\n①对某些客体或处境有强烈恐惧，恐惧和程度与实际危险不相称；\n②发作时有焦虑和自主神经症状；\n③有反复或持续的回避行为 ；\n④知道恐惧过分、不合理、或不必要，但无法控制；\n3  对恐惧情景和事物的回避必需是或曾经是突出症状；\n4  排除焦虑症、分裂症、疑病症。"}]},{"code":"43.2","name":"焦虑症","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"是一种以焦虑情绪为主的神经症。主要分为惊恐障碍和广泛性焦虑两种。焦虑症的焦\n虑症状是原发的，凡继发于高血压、冠心病、甲状腺机能亢进等躯体疾病的焦虑应诊断为\n焦虑综合征。其他精神病理状态如幻觉、妄想、强迫症、疑病症、抑郁症、恐惧症等伴发\n的焦虑，不应诊断为焦虑症。"}]},{"code":"43.3","name":"强迫症","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"指一种以强迫症状为主的神经症，其特点是有意识的自我强迫和反强迫并存，二者强\n烈冲突使病人感到焦虑和痛苦；病人体验到观念或冲动系来源于自我，但违反自己意愿，\n虽极力抵抗，却无法控制；病人也意识到强迫症状的异常性，但无法摆脱。病程迁延者要\n以仪式动作为主而精神痛苦减轻，但社会功能严重受损。"},{"section":"症状标准","text":"1  符合神经症的诊断标准，并以强迫症状为主，至少有下列1 项：\n①以强迫思想为主，包括强迫观念、回忆或表象、强迫性对立观念、穷思竭虑、害怕\n丧失自控能力等；\n②以强迫行为（动作）为主，包括反复洗涤、核对、检查，或询问等；\n③上述的混合形式；\n2  病人称强迫症状起源于自己内心，不是被别人或外界影响强加的；\n3  强迫症状反复出现，病人认为没有意义，并感到不快，甚至痛苦，因此试力抵抗，\n但不能奏效。"},{"section":"严重标准","text":"社会功能受损。"},{"section":"病程标准","text":"符合症状标准至少已3 个月。"},{"section":"排除标准","text":"1  排除其他精神障碍的继发性强迫症状，如精神分裂症、抑郁症，或恐惧症等；\n2  排除脑器质性疾病特别是基底节病变的继发性强迫症状。"}]},{"code":"43.4","name":"躯体形式障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"是一种以持久地担心或相信各种躯体症状的优势观念为特征的神经症。病人因这些症\n状反复就医，各种医学检查阴性和医生的解释，均不能打消其疑虑。即使有时存在某种躯\n体障碍也不能解释所诉症状的性质、程度，或其痛与优势观念。经常伴有焦虑或抑郁情绪。\n尽管症状的发生和持续与不愉快的生活事件、困难或冲突密切相关，但病人常否认心理因\n素的存在。本障碍男女均有，为慢性波动性病程。"},{"section":"症状标准","text":"1  符合神经症的诊断标准；\n2  以躯体症状为主至少有下列1 项：\n①对躯体症状过分担心（严重性与实际情况明显不相称），但不是妄想；\n②对身体健康过分关心，如对通常出现的生理现象和异常感觉过分关心，但不是妄想；\n③反复就医或要求医学检查，但检查结果阴性和医生的合理解释，均不能打消其疑虑。"},{"section":"严重标准","text":"社会功能受损。"},{"section":"病程标准","text":"符合症状标准至少已3 个月。"},{"section":"排除标准","text":"排除其他神经症怕障碍（如疑病症、焦虑、惊恐障碍，或强迫症）、抑郁症、\n精神分裂症、偏执性精神病。"},{"section":"说明","text":"本障碍有时合并存在某种躯体障碍，必须注意以免漏诊。"}]},{"code":"43.5","name":"神经衰弱","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"指一种以脑和躯体功能衰弱为主的神经症，以精神易兴奋却又易疲劳为特征，表现为紧张、\n烦恼、易激惹等情感症状，及肌肉紧张性疼痛和睡眠障碍等生理功能紊乱症状。这些症状\n不是继发于躯体或脑的疾病，也不是其他任何精神障碍的一部分/多缓慢起病，就诊时往\n往已有数月的病程，并可追溯导致长期精神紧张、疲劳的应激因素。偶有突然失眠或头痛\n起病，却无明显原因者。病程持续或时轻时重。近世纪，神经衰弱的概念经历了一系列变\n迁，随着医生对神经衰弱认识的变化和各种特殊综合征和亚型的分出，在美国和西欧已不\n作此诊断，CCMD-3 工作组的现场测试证明，在我国神经衰弱的诊断也明显减少。"},{"section":"症状标准","text":"1  符合神经症的诊断标准；\n2  以脑和躯体功能衰弱症状为主，特征是持续和令人苦恼的脑力易疲劳（如感到没有\n精神，自感脑子迟钝，注意不集中或不持久，记忆差，思考效率下降）和体力易疲劳，经\n过休息或娱乐不能恢复，并至少有下列2 项：\n①情感症状，如烦恼、心情紧张、易激惹，等常与现实生活中的各种矛盾有关，感到\n困难重重，难以应付。可有焦虑或抑郁，但不占主导地位；\n②兴奋症状，如感到精神易兴奋（如回忆和联想增多，主要是对指向性思维感费力，\n而非指向性思维却很活跃，因难以控制而感到痛苦和不快），但无言语运动增多。有时对\n声光很敏感；\n③肌肉紧张性疼痛（如紧张性头痛、肢体肌肉酸痛）或头晕；\n④睡眠障碍，如入睡困难、多梦、醒后感到不解乏，睡眠感丧失，睡眠觉醒节律紊乱；\n⑤其他心理生理障碍。如头晕眼花、耳鸣、心慌、胸闷、腹胀、消化不良、尿频、多\n汗、阳痿、早泄，或月经紊乱等；"},{"section":"严重标准","text":"病人因明显感到脑和躯体功能衰弱，影响其社会功能，为此感到痛苦或主动\n求治。"},{"section":"病程标准","text":"符合症状标准至少已3 个月。"},{"section":"排除标准","text":"1  排除以上任何一种神经症亚型；\n2  排除分裂症、抑郁症。"},{"section":"说明","text":"1  神经衰弱症状若见于神经症的其他亚型，只诊断其他相应类型的神经症；\n2  神经衰弱症状常见于各种脑器质性疾病和其他躯体疾病，此时应诊断为这些疾病的\n神经衰弱综合征。"}]},{"code":"43.9","name":"其他或待分类的神经症","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"诊断标准","text":"1  指病人主诉的症状主要不是通过自主神经系统中介，并仅仅局限于身体的特定系统\n或部位；\n2  在时间上与应激性事件或与当前面临的困难和问题密切相关并能引起对病人注意的\n明显增加（人际关系或医疗方面）的主诉症状，例如疼痛、肿胀感、皮肤蚁行感以及感觉\n异常（麻刺感或麻木感）；\n3  通过检查表明并非躯体疾病所致；\n4  咽喉部哽咽感引起吞咽难等各种形式的吞咽困难；心因性斜颈及其他痉挛性障碍（不\n包括Tourette 综合征等属于童年或少年期抽动障碍者）；心因性瘙痒症（不包括特殊皮肤\n损害，如，斑秃、皮炎、湿疹、或心因性荨麻疹）；心因性痛经（不包括性交疼痛或性冷\n淡等），也归属本类。"}]},{"code":"43.11","name":"场所恐惧症","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"诊断标准","text":"1  符合恐惧症的诊断标准；\n2  害怕对象主要为某些特定环境，如广场、闭室、黑暗场所、拥挤的场所、交通工具\n（如拥挤的船舱、火车车厢）等，其关键临床特征之一是过分担心处于上述情境时没有即\n刻能用的出口；\n3  排除其他恐惧障碍。"}]},{"code":"43.12","name":"社义恐惧症（社会焦虑恐惧症）","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"诊断标准","text":"1  符合恐惧症的诊断标准；\n2  害怕对象主要为社交场合（如在公共场合进食或说话、聚会、开会，或怕自己作出\n一些难堪的行为等）和人际接触（如在公共场合与人接触、怕与他人目光对视，或怕在与\n人群相对时被人审视等）；\n3  常伴有自我评价和害怕批评；\n4  排除其他恐惧障碍。"}]},{"code":"43.13","name":"特定的恐惧症","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"诊断标准","text":"1  符合恐惧症的诊断标准；\n2  害怕对象是场所恐惧和社交恐惧未包括特定物体或情境，如动物（如昆虫、鼠、蛇\n等）、高处、黑暗、雷电、鲜血、外伤、打针、手术，或尖锐锋利物品等；\n3  排除其他恐惧障碍。"}]},{"code":"43.21","name":"惊恐障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"是一种以反复的惊恐发作为主要原发症状的神经症。这种发作并不局限于任何特定的\n情境，具有不可预测性。惊恐发作为继发症状，可见于多种不同的精神障碍，如恐惧性神\n经症、抑郁症等，并应与某些躯体疾病鉴别，如癫痫、心脏病发作、内分泌失调等。"},{"section":"症状标准","text":"1  符合神经症的诊断标准；\n2  惊恐发作需符合以下4 项：\n①发作无明显诱因、无相关的特定情境，发作不可预测；\n②在发作间歇期，除害怕再发作外，无明显症状；\n③发作时表现强烈的恐惧、焦虑，及明显的自主神经症状，并常有人格解体、现实解\n体、濒死恐惧，或失控感等痛苦体验；\n④发作突然开始，迅速达到高峰，发作时意识清晰，事后能回忆"},{"section":"严重标准","text":"病人因难以忍受又无法解脱，而感到痛苦。"},{"section":"病程标准","text":"在1 个月内至少有3 次惊恐发作，或在首次发作后继发害怕再发作的焦虑持\n续1 个月。"},{"section":"排除标准","text":"1  排除其他精神障碍，如恐惧症、抑郁症，或躯体形式障碍等继发的惊恐发作；\n2  排除躯体疾病如癫痫、心脏病发作、嗜铬细胞瘤、甲亢或自发性低血糖等继发的惊\n恐发作。"}]},{"code":"43.22","name":"广泛性焦虑","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"指一种以缺乏明确对象和具体内容的提心吊胆，及紧张不安为主的焦虑症，并有显著\n的植物神经症状、肌肉紧张，及运动性不安。病人因难以忍受又无法解脱，而感到痛苦。"},{"section":"症状标准","text":"1  符合神经症的诊断标准；\n2  以持续的原发性焦虑症状为主，并符合下列2 项：\n①以常或持续的无明确对象和固定内容的恐惧或提心吊胆；\n②伴自主神经症状或运动性不安。"},{"section":"严重标准","text":"社会功能受损，病人因难以忍受又无法解脱，而感到痛苦。"},{"section":"病程标准","text":"符合症状标准至少已6 个月。"},{"section":"排除标准","text":"1  排除甲状腺机能亢进、高血压、冠心病等躯体疾病的继发性焦虑；\n2  排除兴奋药物过量、催眠镇静药物，或抗焦虑药的戒断反应，强迫症、恐惧症、疑\n病症、神经衰弱、躁狂症、抑郁症，或精神分裂症等伴发的焦虑。"}]},{"code":"43.41","name":"躯体化障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"是一种经多种多样、经常变化的躯体症状为主的神经症。症状可涉及身体的任何系统\n或器官，最常见的是胃肠道不适（如疼痛、打嗝、返酸、呕吐、恶心等），异常的皮肤感\n觉（如瘙痒、烧灼感、刺痛、麻木感、酸痛等），皮肤斑点，性及月经方面的主诉也很常\n见，常存在明显的抑郁和焦虑。常为慢性波动性病程，常伴有社会、人际及家庭行为方面\n长期存在的严重障碍。女性远多于男性，多在成年早期发病。"},{"section":"症状标准","text":"1  符合躯体形式障碍的诊断标准；\n2  以多种多样、反复出现、经常变化的躯体症状为主，在下列4 组症状之中，至少有\n2 组共6 项：\n①胃肠道症状，如：腹痛；恶心；腹胀或胀气；嘴里无味或舌苔过厚；呕吐或反胃；\n大便次数多、稀便，或水样便 ；\n②呼吸循环系症状，如：气短；胸痛；\n③泌尿生殖系症状，如：排尿困难或尿频；生殖器或其周围不适感；异常的或大量的\n阴道分泌物；\n④皮肤症状或疼痛症状，如：疤痕；肢体或关节疼痛、麻木，或刺痛感；\n3  体检和实验室检查不能发现躯体障碍的证据，能对症状的严重性、变异性、持续性\n或继发的社会功能损害作出合理解释；\n4  对上述症状的优势观念使病人痛苦，不断求诊，或要求进行各种检查，但检查结果\n阴性和医生的合理解释，均不能打消其疑虑；\n5  如存在自主神以活动亢进的症状，但不占主导地位 。"},{"section":"严重标准","text":"常伴有社会、人际及家庭行为方面长期存在的严重障碍。"},{"section":"病程标准","text":"符合症状标准和严重标准至少已2 年。"},{"section":"排除标准","text":"排除精神分裂症及其相关障碍、心境精神障碍、适应障碍，或惊恐障碍。"}]},{"code":"43.42","name":"未分化躯体形式障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"诊断标准","text":"1  躯体症状的主诉具有多样性、变异性的特点，但构成躯体化障碍的典型性不够，应\n考虑本诊断；\n2  除病程短于2 年外符，合躯体化障碍的基余标准。"}]},{"code":"43.43","name":"疑病症","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"是一种以担心或相信患严重躯体疾病的持久性优势观念为主的神经症，病人因为这种\n症状反复就医，各种医学检查阴性和医生的解释，均不能打消其疑虑。即使病人有时存在\n某种躯体障碍，也不能解释所诉症状的性质、程度，或病人的痛苦与优势观念，常伴有焦\n虑或抑郁。对身体畸形（虽然根据不足）的疑虑或优势观念也属于本症。本障碍男女均有，\n无明显家庭特点（与躯体化障碍不同），常为慢性波动性病程。"},{"section":"症状标准","text":"1  符合神经症的诊断标准；\n2  以疑病症状为主至少有下列1 项：\n①对躯体疾病过分担心，其严重程度与实际情况明显不相称；\n②对健康状况，如通常出现的生理现象和异常感觉作出疑病性解释，但不是妄想；\n③牢固的疑病观念，缺乏根据，但不是妄想；\n3  反复就医或要求医学检查，但检查结果阴性和医生的合理解释，均不能打消其疑虑。"},{"section":"严重标准","text":"社会功能受损。"},{"section":"病程标准","text":"符合症状标准至少已3 个月。"},{"section":"排除标准","text":"排除躯体化障碍、其他神经症性障碍（如焦虑、惊恐障碍，或强迫症）、抑郁\n症、精神分裂症、偏执性精神病。"}]},{"code":"43.44","name":"躯体形式自主神经紊乱","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"是一种主要受自主神经支配的器官系统（如心血管、胃肠道、呼吸系统）发生躯体障\n碍所致的神经症样综合症。病人在自主神经兴奋症状（如心悸、出汗、脸红、震颤）基础\n上，又发生了非特异，的但更有个体特征和主观性的症状，如部位不定的疼痛、烧灼感、\n沉重感、紧束感、肿胀感，经检查这些症状都不能证明有关器官和系统发生了躯体障碍。\n因此本障碍的特征在于明显的自主神经受累，非特异性的症状附加了主观的主诉，以及坚\n持将症状归咎于某一特定的器官或系统。"},{"section":"诊断标准","text":"1  符合躯体形式障碍的诊断标准；\n2  至少有下列2 项器官系统（心血管、呼吸、食管和胃、胃肠道下部、泌尿生殖系统）\n的自主神经兴奋体征：\n①心悸；\n② 出汗；\n③口干；\n④脸发烧或潮红；\n3  至少有下列1 项病人主诉的症状：\n①胸痛或心前区不适；\n②呼吸困难或过度换气；\n③轻微用力即感过度疲劳；\n④吞气、呃逆、胸部或上腹部的烧灼感等；\n⑤上腹部不适或胃内翻腾或搅拌感；\n⑥大便次数增加；\n⑦尿频或排尿困难；\n⑧肿胀感、膨胀感或沉重感；\n4  没有证据表明病人所忧虑的器官系统存在结构或功能的紊乱。\n5  并非仅见于恐惧障碍或惊恐障碍发作时。"}]},{"code":"43.45","name":"持续性躯体形式疼痛障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"是一种不能用生理过程或躯体障碍予以合理解释的持续、严重的疼痛。情绪冲突或心\n理社会问题直接导致了疼痛的发生，经过检查未发现相应主诉的躯体病变。病程迁延，常\n持续6 个月以上，并使社会功能受损。诊断需排除抑郁症或精神分裂症病程中被假定为心\n因性疼痛的疼痛、躯体化障碍，以及检查证实的相关躯体疾病与疼痛。"},{"section":"症状标准","text":"1  符合躯体形式障碍的诊断标准；\n2  持续、严重的疼痛，不能用生理过程或躯体疾病作出合理解释；\n3  情感冲突或心理社会问题直接导致疼痛的发生；\n4  经检查未发现与主诉相应的躯体病变。"},{"section":"严重标准","text":"社会功能受损或困难以摆脱的精神痛苦而主动求治。"},{"section":"病程标准","text":"符合症状标准至少已6 个月。"},{"section":"排除标准","text":"1  排除检查出的相关躯体疾病与疼痛。\n2  排除精神分裂症或相关障碍、心境障碍、躯体化障碍、未分化的躯体形式障碍、疑\n病症。"}]},{"code":"43.49","name":"其他或待分类躯体形式障碍","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[]},{"code":"43.441","name":"心血管系统功能紊乱","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"包括心脏神经症、神经循环衰弱、DaCosta 综合征。"}]},{"code":"43.442","name":"高位胃肠道功能紊乱","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"包括心因性吞气症、呃逆、胃神经症。"}]},{"code":"43.443","name":"低位胃肠道功能紊乱","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"包括心因性激惹综合征、心因性腹泻、胀气综合征。"}]},{"code":"43.444","name":"呼吸系统功能紊乱","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"包括过度换气症。"}]},{"code":"43.445","name":"泌尿生殖系统功能紊乱","block":"4 癔症、应激相关障碍、神经症","blockEn":"Hysteria, stress-related disorders, neurosis","criteria":[{"section":"说明","text":"包括心因性尿频和排尿困难。"}]},{"code":"50.1","name":"神经性厌食","block":"5 心理因素相关生理障碍","blockEn":"Physiological disorders related to psychological factors","criteria":[{"section":"诊断标准","text":"1  明显的体重减轻比正常平均体重减轻15%以上，或者Quetelet 体重指数为17.5 或更低，或在青春期前不有达到所期望的躯体增长标准，并有发育延迟或停止；\n2  自大故意造成体重减轻，至少有下列1 项：\n①回避“导致发胖的食物”；\n②自我诱发呕吐；\n③自我引发排便；\n④过度运动；\n⑤服用厌食剂或利尿剂等；\n3  常可有病理性怕胖：指一种持续存在的异乎寻常地害怕发胖的超价观念，并且病人给自己制订一个过低的体重界限，这个界值远远低于其病前医生认为是适度的或健康的体重；\n4  常可有下丘脑—垂体—性腺轴的广泛内分泌紊乱。女性表现为闭经（停经至少已3个连续月经周期，但妇女如用激素替代治疗可出现持续阴道出血，最常见的是用避孕药），男性表现为性兴趣丧失或性功能低下。可有生长激素升高，皮质醇浓度上升，外周甲状腺代谢异常，及胰岛素分泌异；\n5  常症状至少已3 个月；\n6  可有间歇发作的暴饮暴食（此时只诊断为神经性厌食）；\n7  排除躯体疾病所致的体重减轻（如脑瘤、肠道疾病例如Crohn 病或吸收不良综合征等）。"}],"nameEn":"Anorexia nervosa"},{"code":"50.2","name":"神经性贪食","block":"5 心理因素相关生理障碍","blockEn":"Physiological disorders related to psychological factors","criteria":[{"section":"诊断标准","text":"1  存在一种持续的难以控制的进食和渴求食物的优势观念，并且病人屈从于短时间内摄入大量食物的贪食发作；\n2  至少用下列一种方法抵消食物的发胖作用：\n①自我诱发呕吐；\n②滥用泻药；\n③间歇禁食；\n④使用厌食剂、甲状腺素类制剂或利尿剂。如果是糖尿病人可能会放弃胰岛素治疗；\n3  常有病理性怕胖；\n4  常有神经性厌食既往史，二者间隔数月至数年不等；\n5  发作性暴食至少每周2 次，持续3 个月；\n6  排除神经系统器质性病变所致的暴食，及癫痫、精神分裂症等精神障碍继发的暴食。"}],"nameEn":"Bulimia nervosa"},{"code":"50.3","name":"神经性呕吐","block":"5 心理因素相关生理障碍","blockEn":"Physiological disorders related to psychological factors","criteria":[{"section":"诊断标准","text":"1  自发的或故意诱发的反复发生于进食后的呕吐，呕吐物为刚吃进的食物；\n2  体重减轻不显著（体重保持在正常平均体重值的80%以上）；\n3  可有害怕发胖或减轻体重的想法 ；\n4  这种呕吐几乎每天发生，并至少已持续1 个月；\n5  排除躯体疾病导致的呕吐以及癔症或神经症等。"}],"nameEn":"Psychogenic vomiting"},{"code":"51.1","name":"失眠症","block":"5 心理因素相关生理障碍","blockEn":"Physiological disorders related to psychological factors","criteria":[{"section":"症状标准","text":"1  几乎以失眠为惟一的症状，包括难以入睡、睡眠不深、多梦、早醒，或醒后不易再睡、醒后不适感、疲乏，或白天困倦等；\n2  具有失眠和极度关注失眠结果的优势观念。"},{"section":"严重标准","text":"对睡眠数量、质量的不满引起明显的苦恼或社会功能受损。"},{"section":"病程标准","text":"至少每周发生3 次，并至少已1 个月。"},{"section":"排除标准","text":"排除躯体疾病或精神障碍症状导致的继发性失眠。"}],"nameEn":"Insomnia"},{"code":"51.2","name":"嗜睡症","block":"5 心理因素相关生理障碍","blockEn":"Physiological disorders related to psychological factors","criteria":[{"section":"症状标准","text":"1  白天睡眠过多或睡眠发作；\n2  不存在睡眠时间不足；\n3  不存在从唤醒到完全清醒的时间延长或睡眠中呼吸暂停；\n4  无发作性睡病的附加症状（如猝倒症、睡眠瘫痪、入睡前幻觉、醒前幻觉等）。"},{"section":"严重标准","text":"病人为此明显感到痛苦或影响社会功能。"},{"section":"病程标准","text":"几乎每天发生，并至少已1 个月。"},{"section":"排除标准","text":"不是由于睡眠不足、药物、酒精、躯体疾病所致，也不是某种精神障碍的症状组成部分。"}],"nameEn":"Hypersomnia"},{"code":"51.3","name":"睡眠—觉醒节律障碍","block":"5 心理因素相关生理障碍","blockEn":"Physiological disorders related to psychological factors","criteria":[{"section":"症状标准","text":"1  病人的睡眠—觉醒节律与所要求的（即与病人所在环境的社会要求和大多数人遵循的节律）不符；\n2  病人在主要的睡眠时段失眠，而在应该清醒时段出现嗜睡。"},{"section":"严重标准","text":"明显感到苦恼或社会功能受损。"},{"section":"病程标准","text":"几乎每天发生，并至少已1 个月。"},{"section":"排除标准","text":"排除躯体疾病或精神障碍（如抑郁症）导致的继发性睡眠—觉醒节律障碍。"}],"nameEn":"Sleep-wake rhythm disorder"},{"code":"51.4","name":"睡行症","block":"5 心理因素相关生理障碍","blockEn":"Physiological disorders related to psychological factors","criteria":[{"section":"症状标准","text":"1  反复发作的睡眠中起床行走。发作时，睡行者表情茫然、目光呆滞，对别人的招呼或干涉行为相对缺乏反应，要使病人清醒相当困难。\n2  发作后自动回到床上继续睡觉或躺在地上继续睡觉；\n3  尽管在发作后的苏醒初期，可有短暂意识和定向障碍，但几分钟后，即可恢复常态，不论是即刻苏醒或次晨醒来均完全遗忘。"},{"section":"严重标准","text":"不明显影响日常生活和社会功能。"},{"section":"病程标准","text":"反复发作的睡眠中起床行走数分钟至半小时。"},{"section":"排除标准","text":"1  排除器质性疾病（如痴呆、癫痫等）导致的继发性睡眠—觉醒节律障碍，但可与癫痫并存，应与癫痫性发作鉴别；\n2  排除癔症。"}],"nameEn":"Sleepwalking"},{"code":"51.5","name":"夜惊","block":"5 心理因素相关生理障碍","blockEn":"Physiological disorders related to psychological factors","criteria":[{"section":"诊断标准","text":"1  反复发作的在一声惊恐性尖叫后从睡眠中醒来，不能与环境保持适当接触，并伴有强烈的焦虑、躯体运动，及自主神经功能亢进（如心动过速、呼吸急促，及出汗等），约持续1~10 分钟，通常发生在睡眠初三分之一阶段；\n2  对别人试图干涉夜惊发作的活动相对缺乏反应，若干涉几乎总是出现至少几分钟的定向障碍和持续动作；\n3  事后遗忘，即使能回忆，出极有限；\n4  排除器质性疾病（如痴呆、脑瘤、癫痫等）导致的继发性夜惊发作，也需排除热性凉劂。"}],"nameEn":"Night terrors"},{"code":"51.6","name":"梦魇","block":"5 心理因素相关生理障碍","blockEn":"Physiological disorders related to psychological factors","criteria":[{"section":"诊断标准","text":"1  从夜间睡眠或午睡中惊醒，并能清晰和详细地回忆强烈恐惧的梦境，这些梦境通常危及生存、安全，或自尊。一般发处于睡眠的后半夜。\n2  一旦从恐怖的梦境中惊醒，病人能迅速恢复定向和完全苏醒；\n3  病人感到非常痛苦。"}],"nameEn":"Nightmares"},{"code":"52","name":"非器质性性功能障碍","block":"5 心理因素相关生理障碍","blockEn":"Physiological disorders related to psychological factors","criteria":[{"section":"症状标准","text":"成年人不能进行自己所希望的性活动。"},{"section":"严重标准","text":"对日常生活或社会功能有所影响。"},{"section":"病程标准","text":"符合症状标准至少已3 个月。"},{"section":"排除标准","text":"不是由于器质性疾病、药物、酒精及衰老所致的性功能障碍，也不是其他精神障碍症状的一部分。"}],"nameEn":"Nonorganic sexual dysfunction"},{"code":"52.1","name":"性欲减退","block":"5 心理因素相关生理障碍","blockEn":"Physiological disorders related to psychological factors","criteria":[{"section":"诊断标准","text":"1  符合非器质性性功能障碍的诊断标准；\n2  性欲减低，甚至丧失，表现为性欲望、性爱好，及有关的性思考或性幻想缺乏；\n3  症状至少已持续3 个月。"}],"nameEn":"Hypoactive sexual desire"},{"code":"52.2","name":"阳痿","block":"5 心理因素相关生理障碍","blockEn":"Physiological disorders related to psychological factors","criteria":[{"section":"诊断标准","text":"1  男性符合非器质性性功能障碍的诊断标准；\n2  性交时不能产生阴道性交所需的充分阴茎勃起（阳痿），至少有下列1 项：\n①在作爱初期（阴道性交前）可充分勃起，但正要性交时或射精前，勃起消失或减退；\n②能部分勃起，但不充分，不足以性交；\n③不产生阴茎的膨胀；\n④从未有过性交所需的充分勃起；\n⑤仅在没有考虑性交时，产生于勃起。"}],"nameEn":"Impotence"},{"code":"52.3","name":"冷阴","block":"5 心理因素相关生理障碍","blockEn":"Physiological disorders related to psychological factors","criteria":[{"section":"诊断标准","text":"1  女性符合非器质性性功能障碍的诊断标准；\n2  性交时生殖器反应不良，如阴道湿润差和阴唇缺乏适当的膨胀，至少有下列1 项：\n①在作爱初期（阴道性交前）有阴道湿润，但不能持续到使阴茎舒适地进入；\n②在所有性交场合，都没有阴道湿润；\n③某些情况下可产生正常的阴道湿润（如和某个性伙伴、或手淫过程中，或并不打算进行阴道性交时）。"}],"nameEn":"Female sexual arousal disorder"},{"code":"52.4","name":"性乐高潮障碍","block":"5 心理因素相关生理障碍","blockEn":"Physiological disorders related to psychological factors","criteria":[{"section":"诊断标准","text":"1  符合非器质性性功能障碍的诊断标准；\n2  从未体验到性乐高潮（原发性）或有一段性交反应相对正常，然后发生性乐高潮障碍（继发性）可进一步分为：\n①普遍性性乐高潮障碍，发生于所有的性活动中和任何性伙伴在一起时；\n②男性的境遇性性乐高潮障碍，至少有下列1 项：性乐高潮仅发生于睡眠中，从不发生于清醒状态；与性伙伴在一起时从无性乐高潮；与性伙伴在一起时出现性乐高潮，但不是阴茎在进入或保持在阴道内的时候；\n③女性在某些情况下可有性乐高潮，但明显减少。"}],"nameEn":"Orgasmic dysfunction"},{"code":"52.5","name":"早泄","block":"5 心理因素相关生理障碍","blockEn":"Physiological disorders related to psychological factors","criteria":[{"section":"诊断标准","text":"1 符合非器质性性功能障碍的诊断标准；\n2 不能推迟射精以充分享受作爱，并至少有下列1 项：\n①射精发生在进入阴道前夕或刚刚进入阴道后；\n②在阴茎尚未充分勃起进入阴道的情况下射精；\n3 并非因性行为节制，继发阳痿或早泄。"}],"nameEn":"Premature ejaculation"},{"code":"52.6","name":"阴道痉挛","block":"5 心理因素相关生理障碍","blockEn":"Physiological disorders related to psychological factors","criteria":[{"section":"诊断标准","text":"1  符合非器质性性功能障碍的诊断标准；\n2  阴道周围肌群的痉挛阻止了阴茎进入阴道或使进入不舒服，至少有下列1 项：\n①原发性阴道痉挛，指从未有过正常反应；\n②继发性阴道痉挛，指一段性活动的反应相对正常，然后发生阴道痉挛；当不进行阴道性交时，可产生正常的性反应；对任何性接触的企图都恐惧，并力图避免阴道性交。"}],"nameEn":"Vaginismus"},{"code":"52.7","name":"性交疼痛","block":"5 心理因素相关生理障碍","blockEn":"Physiological disorders related to psychological factors","criteria":[{"section":"诊断标准","text":"1  符合非器质性性功能障碍的诊断标准；\n2  男性在性活动过程中感到疼痛或不舒服；\n3  女性在阴道性交的全过程或在阴茎插入很深时发生的疼痛，不能归因于阴道痉挛或阴道湿润差。"}],"nameEn":"Dyspareunia"},{"code":"60","name":"人格障碍","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"症状标准","text":"个人的内心体验与行为特征（不限于精神障碍发作期）在整体上与其文化所期望和所接受的范围明显偏离，这种偏离是广泛、稳定和长期的，并至少有下列1 项：\n1  认知（感知，及解释人和事物，由此形成对自我及他人的态度和形象的方式）的异常偏离；\n2  情感（范围、强度，及适切的情感唤起和反应）的异常偏离；\n3  控制冲动及对满足个人需要的异常偏离；\n4  人际关系的异常偏离。"},{"section":"严重标准","text":"特殊行为模式的异常偏离，使病人或其他人（如家属）感到痛苦或社会适应不良。"},{"section":"病程标准","text":"开始于童年、青少年期，现年18 岁以上至，少已持续2 年。"},{"section":"排除标准","text":"人格特征的异常偏离并非躯体疾病或精神障碍的表现或后果。"}],"nameEn":"Personality disorders"},{"code":"60.1","name":"偏执性人格障碍","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"1  符合人格障碍的诊断标准；\n2  以猜疑和偏执为特点，并至少有下列3 项：\n①对挫折和遭遇过度敏感；\n②对侮辱和伤害不能宽容，长期耿耿于怀；\n③多疑，容易将别人的中性或友好行为误解为敌意或轻视；\n④明显超过实际情况所需的好斗对个人权利执意追求；\n⑤易有病理性嫉妒，过分怀疑恋人有新欢或伴侣不忠，但不是妄想；\n⑥过分自负和自我中心的倾向，总感觉受压制、被迫害，甚至上告、上访，不达目的不肯罢休；\n⑦具有将其周围或外界事件解释为“阴谋”等的非现实性优势观念，因此过分警惕和抱有敌意。"}],"nameEn":"Paranoid personality disorder"},{"code":"60.2","name":"分裂样人格障碍","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"1  符合人格障碍的诊断标准；\n2  以观念、行为和外貌装饰的奇特、情感冷淡，及人际关系缺陷为特点，并至少有下列3 项：\n①性格明显内向（孤独、被动、退缩），与家庭和社会疏远，除生活或工作中必须接触的人外，基本不与他人主动交往，缺少知心朋友，过分沉湎于幻想和内省；\n②表情呆板，情感冷淡，甚至不通人情，不能表达对他人的关心、体贴、及愤怒等；\n③对赞扬和批评反应差或无动于衷；\n④缺乏愉快感；\n⑤缺乏亲密、信任的人际关系；\n⑥在遵循社会规范方面存在困难，导致行为怪异；\n⑦对与他人之间的性活动不感兴趣（考虑年龄）。"}],"nameEn":"Schizoid personality disorder"},{"code":"60.3","name":"反社会性人格障碍","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"1  符合人格障碍的诊断标准，并至少有下列3 项：\n①严重和长期不负责任，无视社会常规、准则、义务等，如不能维持长久的工作（或学习）经常旷工（或旷课）多次无计划地变换工作；有违反社会规范的行为，且这修缮行为已构成拘捕的理由（不管拘捕与否）；\n②行动无计划或有冲动性，如进行事先未计划的旅行；\n③不尊重事实，如经常撒谎、欺骗他人，以获得个人利益；\n④对他人漠不关心，如经常不承担经济义务、拖欠债务、不瞻养子女或父母；\n⑤不能维持与他人的长久的关系，如不能维持长久的（1 年以上）夫妻关系；\n⑥很容易责怪他人，或对其与社会相冲突的行为进行无理辩解；\n⑦对挫折的耐受性低，微小刺激便可引起冲动，甚至暴力行为；\n⑧易激惹，并有暴力行为，如反复斗殴或攻击别人，包括无故殴打配偶或子女；\n⑨危害别人时缺少内疚感，不能从经验，特别是在受到惩罚的经验中获益。\n2  在18 岁前有品行障碍的证据，至少有下列3 项：\n⑴反复违反家规或校规；\n⑵反复说谎（不是为了躲避体罚）；\n⑶习惯必吸烟，喝酒；\n⑷虐待动物或弱小同伴；\n⑸反复偷窃；\n⑹经常逃学；\n⑺至少有2 次未向家人说明外出外出过夜\n⑻过早发生性活动\n⑼多次参与破坏公共财物活动\n⑽反复挑起或参与斗殴\n⑾被学校开除过，或因行为不轨至少停学一次；\n⑿被拘留或被公安机关管教过。"}],"nameEn":"Dissocial personality disorder"},{"code":"60.4","name":"冲动性人格障碍（攻击性人格障碍）","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"1  符合人格障碍的诊断标准；\n2  以情感爆发和明显的冲动行为作为主要表现，并至少有下列3 项：\n①易与他人发生争吵和冲突，特别在冲动行为受阻或受到批评时；\n②有突发的愤怒和暴力倾向，对导致的冲动行为不能自控；\n③对事物的计划和预见能力明显受损；\n④不能坚持任何没有即刻奖励的行为；\n⑤不稳定的和反复无常的心境；\n⑥自我形象、目的，及内在偏好（包括性欲望）的紊乱和不确定；\n⑦容易产生人际关系的紧张或不稳定，时常导致情感危机；\n⑧经常出现自杀、自伤行为。"}],"nameEn":"Impulsive personality disorder"},{"code":"60.5","name":"表演性（癔症性）人格障碍","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"1  符合人格障碍的诊断标准；\n2  以过分的感情用事或夸张言行，吸引他人的注意为特点，并至少有下列3 项：\n①富于自我表演性、戏剧性、夸张性地表达情感；\n②肤浅和易变的情感；\n③自我中心，自我放纵和不为他人着想；\n④追求刺激和以自己为注意中心的活动；\n⑤不断渴望受到赞赏，情感易受伤害；\n⑥过分关心躯体的性感，以满足自己的需要；\n⑦暗示性高，易受他人影响。"}],"nameEn":"Histrionic (hysterical) personality disorder"},{"code":"60.6","name":"强迫性人格障碍","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"1  符合人格障碍的诊断标准；\n2  以过分的谨小慎微、严格要求与完美主义，及内心的不安全感为特征，并至少有下列3 项：\n①因个人内心深处的不安全感导致优柔寡断、怀疑，及过分谨慎；\n②需在很早以前就对所有的活动作出计划并不厌其烦；\n③凡事需反复核对，因对细节的过分注意，以致忽视全局；\n④经常被讨厌的思想或冲动所困扰，但尚未达到强迫症的程度；\n⑤过分谨慎多虑、过分专注于工作成效而不顾个人消遣，及人际关系；\n⑥刻板和固执，要求别人按其规矩办事；\n⑦因循守旧、缺乏表达温情的能力。"}],"nameEn":"Anankastic personality disorder"},{"code":"60.7","name":"焦虑性人格障碍","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"1  符合人格障碍的诊断标准；\n2  以持久和广泛的内心紧张，及忧虑体验为特征，并至少有下列3 项：\n①一贯的自我敏感、不安全感，及自卑感；\n②对遭排斥和批评过分敏感；\n③不断追求被人接受和受到欢迎；\n④除非得到保证被他人所接受和不会受到批评，否则拒绝与他人建立人际关系；\n⑤惯于夸大生活中潜在危险因素，达到回避某种活动的程度，但无恐惧性回避；\n⑥因“稳定”和“安全”的需要，生活方式受到限制。"}],"nameEn":"Anxious personality disorder"},{"code":"60.8","name":"依赖性人格障碍","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"1  符合人格障碍的诊断标准；\n2  以过分依赖为特征，并至少有下无3 项：\n①要求或让他人为自己生活的重要方面承担责任；\n②将自己的需要附属于所依赖的人，过分地服从他人的意志；\n③不愿意对所依赖的人提出即使合理的要求；\n④感到自己无助、无能，或缺乏精力；\n⑤沉湎于被遗忘的恐惧之中，为断要求别人对此提出保证，独处时感到难受；\n⑥当与他人的亲密关系结束时，有被毁来和无助的体验；\n⑦经常把责任推给别人，以应对逆境。"}],"nameEn":"Dependent personality disorder"},{"code":"61.1","name":"病理性赌博","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"1  自己诉说具在难以控制的强烈赌博欲望，虽然努力自控，但不能停止赌博；\n2  专注于思考或想象赌博行为或有关情境；\n3  这些赌博发作没有给个人带来收益，或尽管对自己的社会、职业、家庭的价值观和义务，均有不利的影响，仍然赌博；\n4  在1 年中，至少有过3 次赌博发作。"}],"nameEn":"Pathological gambling"},{"code":"61.2","name":"病理性纵火","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"1  自己诉说有强烈的纵火欲望，并有行动前的紧张和行动后的轻松感；\n2  专注于想象纵火行动或行动时的周围情境；\n3  至少有过一次无明显动机的纵火行为或企图。"}],"nameEn":"Pathological fire-setting"},{"code":"61.3","name":"病理性偷窃","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"1  自己诉说具有难以控制的强烈偷窃欲望，虽然努力自控，但不能停止偷窃；\n2  专注于思考或想象偷窃行为或有关情境；\n3  这些偷窃发作没有给个人带来收益，或尽管对自己的社会、职业、家庭的价值观和义务，均有不利的影响，仍然偷窃；\n4  在1 年中，至少有过3 次偷窃发作。"}],"nameEn":"Pathological stealing"},{"code":"61.4","name":"拔毛症（病理性拔毛发）","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"1  引人注目的头发缺失是由于持续的控制拔发的冲动失败所致；\n2  病人诉说有一种强烈的拔发欲望，伴有一种行动前的紧张感和之后的轻松感；\n3  并非皮肤疾病，如皮炎所致，也不是对精神症，状如妄想或幻觉的反应。"}],"nameEn":"Trichotillomania"},{"code":"62.1","name":"性身份障碍","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"女性：\n1  持久和强烈地因自己是女性而感到痛苦，渴望自己是男性（并非因看到任何文化或社会方面的好处，而希望成为男性），或坚持自己是男性，并至少有下列1 项：\n①固执地表明厌恶女装，并坚持穿男装；\n②固执地否定女性解剖结构，至少可由下列1 项证实：明确表示已经有，或将长出阴茎；不愿取蹲位排尿；明确表示不愿意乳房发育或月经来潮；\n2  上述障碍至少已持续6 个月。\n男性：\n1  持久和强烈地为自己是男性而痛苦，渴望自己是女性（并非因看到任何文化或社会方面的好处，而希望成为女性）或坚持自己是女性，并至少有下列1 项：\n①专注于女性常规活动，表现为偏爱女性着装或强烈渴望参加女性的游戏或娱乐活动，拒绝参加男性的常规活动；\n②固执地否定男性解剖结构，至少可由下列1 项证实：断言将长成女人{不仅是角色方面}；明确表示阴茎或睾丸令人厌恶；认为阴茎或睾丸即将消失，或最好没有；\n2  上述障碍至少已持续6 个月。"}],"nameEn":"Gender identity disorders"},{"code":"62.11","name":"易性症","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"1  期望成为异性被别人接受，常希望通过外科手术或激素治疗使自己的躯体尽可能与自己所偏爱的性别一致；\n2  转换性别的认同至少已持续2 年；\n3  不是其他精神障碍（如精神分裂症）的症状，或与染色体异常有关的症状。"}],"nameEn":"Transsexualism"},{"code":"62.21","name":"恋物症","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"1  在强烈的欲望与兴奋的驱使下，反复收集异性使用的物品。所恋之物是极重要的性刺激来源，或为达到满意的性反应所必需；\n2  至少已持续6 个月。"}],"nameEn":"Fetishism"},{"code":"62.22","name":"露阴症","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"1  具有反复或持续地向陌生人（通常是异性）暴露自己生殖器的倾向，几乎总是伴有性唤起及手淫；\n2  没有与“暴露对象”性交的意愿或要求；\n3  此倾向至少已存在6 个月。"}],"nameEn":"Exhibitionism"},{"code":"62.23","name":"窥阴症","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"1  反复窥视异性下身、裸体，或他人性活动，伴有兴奋或手淫，\n2  没有暴露自己的意向；\n3  没有同受窥视者发性性关系的愿望。"}],"nameEn":"Voyeurism"},{"code":"62.24","name":"摩擦症","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"1  反复地通过靠拢陌生人（通常是异性），紧密接触和摩擦自己生殖器；\n2  没有与所摩擦对象性交的要求；\n3  没有暴露自己生殖器的愿望；\n4  这种行为至少已存在6 个月。"}],"nameEn":"Frotteurism"},{"code":"62.25","name":"性施虐与性受虐症","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"1  一种性运动偏爱，可为接受者（受虐狂），或提供者（施虐狂），或两者都有，并至少有下列1 项：\n①疼痛；\n②污辱；\n③捆绑；\n2  施虐—受虐行为是极为重要的刺激来源或为满足性欲所必需；\n3  至少已持续6 个月。"}],"nameEn":"Sadomasochism"},{"code":"62.31","name":"同性恋","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"1  符合性指向障碍的定义；\n2  在正常生活条件下，从少年时期就开始对同性成员持续表现性爱倾向，包括思想、感情，及性爱行为；\n3  对异性虽可有正常的性行为，但性爱倾向明显减弱或缺乏，因此难以建立和维持与异性成员的家庭关系。"}],"nameEn":"Homosexuality"},{"code":"62.32","name":"双性恋","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"1  符合性指向障碍的定义；\n2  在正常生活条件下，从少年时期就开始对同性和异性两种成员均持续表现性爱的迷恋倾向，包括思想、感情，及性爱行为；\n3  难以建立和维持与异性成员的家庭关系。"}],"nameEn":"Bisexuality"},{"code":"62.211","name":"异装症","block":"6 人格障碍、习惯与冲动控制障碍、性心理障碍","blockEn":"Personality disorders, habit and impulse disorders, psychosexual disorders","criteria":[{"section":"诊断标准","text":"1  穿着异性服装以体验异性角色，满足自己的性兴奋不；\n2  期望永久变为异性；\n3  至少已持续6 个月。"}],"nameEn":"Transvestic fetishism"},{"code":"70.1","name":"轻度精神发育迟滞","block":"7 精神发育迟滞与童年和少年期心理发育障碍","blockEn":"Mental retardation, and disorders of psychological development with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  智商在50~69 之间，心理年龄约9~12 岁；\n2  学习成绩差（在普通学校中学习时常不及格或留级）或工作能力差（只能完成较简单的手工劳动）；\n3  能自理生活；\n4  无明显言语障碍，但对语言的理解和使用能力有不同程度的延迟。"}],"nameEn":"Mild mental retardation"},{"code":"70.2","name":"中度精神发育迟滞","block":"7 精神发育迟滞与童年和少年期心理发育障碍","blockEn":"Mental retardation, and disorders of psychological development with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  智商在34~49 之间，心理年龄约6~9 岁；\n2  不能适应普通学校学习，可进行个位数的加、减法计算；可从事简单劳动，但质量低、效率差；\n3  可学会自理简单生活，但需督促、帮助；\n4  可掌握简单生活用语，但词汇贫乏。"}],"nameEn":"Moderate mental retardation"},{"code":"70.3","name":"重度精神发育迟滞","block":"7 精神发育迟滞与童年和少年期心理发育障碍","blockEn":"Mental retardation, and disorders of psychological development with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  智商在20~40 之间，心理年龄约3~6 岁；\n2  表现显著的运动损害或其他相关的缺陷，不能学习和劳动；\n3  生活不能自理；\n4  言语功能严重受损，不能进行有效的语言交流。"}],"nameEn":"Severe mental retardation"},{"code":"70.4","name":"极重度精神发育迟滞","block":"7 精神发育迟滞与童年和少年期心理发育障碍","blockEn":"Mental retardation, and disorders of psychological development with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  智商在20 以下，心理年龄约在3 岁以下；\n2  社会功能完全丧失，不会逃避危险；\n3  生活完全不能自理，大小便失禁；\n4  言语功能丧失。"}],"nameEn":"Profound mental retardation"},{"code":"71.1","name":"特定言语构音障碍","block":"7 精神发育迟滞与童年和少年期心理发育障碍","blockEn":"Mental retardation, and disorders of psychological development with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  发音困难，讲话时发音错误，以致别人很难听懂。患儿说话时的语音省略，歪曲或代替的严重程度，已超过同龄儿童的变异范围；\n2  语言理解和表达能力正常（韦氏儿童智力测验语言智商、操作智商及总智商均≥70；\n3  不是由于听力缺陷、口腔疾病、神经系统疾病、精神发育迟滞，或广泛发育障碍所致。"}],"nameEn":"Specific speech articulation disorder"},{"code":"71.2","name":"表达性语言障碍","block":"7 精神发育迟滞与童年和少年期心理发育障碍","blockEn":"Mental retardation, and disorders of psychological development with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  言语表达能力明显低于实际年龄应有的水平。2 岁时不会说单词，3 岁时不能讲两个单词的短句，稍大后仍有词汇量少，讲话过短，句法错误等，其严重程度超过同龄儿童的变异范围；\n2  语言的理解能力正常；\n3  标准化测验总智商正常（韦氏儿童智力测验操作智商及总智商均≥70）；\n4  不是由于听力缺陷、口腔疾病、神经系统疾病、精神发育迟滞，或广泛发育障碍所致。"}],"nameEn":"Expressive language disorder"},{"code":"71.3","name":"感受性语言障碍","block":"7 精神发育迟滞与童年和少年期心理发育障碍","blockEn":"Mental retardation, and disorders of psychological development with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  言语理解能力低于实际年龄应有的水平。1 岁时对熟悉的名称无反应，2 岁时仍不能听从日常简单的口令，以后又出现不能理解语法结构、不了解别人的语调、手势等意义，其严重程度超过同龄儿童的变异范围；\n2  伴有语言表达能力和发音的异常；\n3  非言语性智力测验智商在正常水平（韦氏儿童智力测验操作智商≥70）；\n4  不是由于听力缺陷、口腔疾病、神经系统疾病、精神发育迟滞，或广泛发育障碍所致。"}],"nameEn":"Receptive language disorder"},{"code":"71.4","name":"伴发癫痫的获得性失语（Landau-Kleffner 综合征）","block":"7 精神发育迟滞与童年和少年期心理发育障碍","blockEn":"Mental retardation, and disorders of psychological development with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  病前语言功能发育正常，在一开始出现言语丧失的前后2 年中，出现累及一侧或双侧颞叶的阵发性脑电图异常或癫痫发作；\n2  非语言智力和听力正常；\n3  表达或感受言语能力严重缺损的总病程不超过6 个月；\n4  不是由于其他神经系统疾病、广泛性发育障碍所致。"}],"nameEn":"Acquired aphasia with epilepsy (Landau-Kleffner syndrome)"},{"code":"72","name":"特定学校技能发育障碍","block":"7 精神发育迟滞与童年和少年期心理发育障碍","blockEn":"Mental retardation, and disorders of psychological development with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  存在某种特定学校技能障碍的证据，标准化的学习技能测验评分明显低于相应年龄和年级儿童的正常水平，或相应智力的期望水平，至少达2 个标准差以上；\n2  特定学校技能 障碍在学龄早期发生并持续存在，严重影响学习成绩或日常生活中需要这种技能的活动；\n3  不是由于缺乏教育机会、神经经系统疾病、视觉障碍、听觉障碍、广泛发育障碍，或精神发育迟滞所致。"}],"nameEn":"Specific developmental disorders of scholastic skills"},{"code":"72.1","name":"特定阅读障碍","block":"7 精神发育迟滞与童年和少年期心理发育障碍","blockEn":"Mental retardation, and disorders of psychological development with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  符合特定学校技能发育障碍的诊断标准；\n2  阅读准确性或理解力明显障碍，标准化阅读技能测验评分低于其相应年龄和年级儿童的正常水平，或相应智力的期望水平，达2 个标准差以上；\n3  有持续存在的阅读困难史，严重影响与阅读技能有关的学习成绩或日常活动。"}],"nameEn":"Specific reading disorder"},{"code":"72.2","name":"特定拼写障碍","block":"7 精神发育迟滞与童年和少年期心理发育障碍","blockEn":"Mental retardation, and disorders of psychological development with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  符合特定学校技能发育障碍的诊断标准；\n2  有文字符号书写表达的学校技能障碍，其准确性和完整性均差，标准化书写表达能力测验评分低于其相应年龄和年级儿童的正常水平或相应智力期望水平，达2 个标准差以上，但阅读与计算技能在正常范围；\n3  有持续存在的书写表达困难史、严重影响与书写表达技能有关的学习成绩或日常活动。"}],"nameEn":"Specific spelling disorder"},{"code":"72.3","name":"特定计算技能障碍","block":"7 精神发育迟滞与童年和少年期心理发育障碍","blockEn":"Mental retardation, and disorders of psychological development with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  符合特定学校技能发育障碍的诊断标准；\n2  有基本运算、推理能力障碍，标准化计算测验的评分低于其相应年龄和年级儿童的正常水平或相应智力期望水平，达2 个标准差以上，但阅读准确性、理解力和书写表达能力在正常范围；\n3  有持续存在的计算困难史，严重影响计算能力有关的学习成绩或日常活动。"}],"nameEn":"Specific disorder of arithmetical skills"},{"code":"73","name":"特定运动技能发育障碍","block":"7 精神发育迟滞与童年和少年期心理发育障碍","blockEn":"Mental retardation, and disorders of psychological development with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  精细或粗大运动的共济协调能力明显低于其年龄应有的水平，或标准化运动技能测验低于其年龄期望值，达2 个标准差以上；\n2  早期发生的运动技能障碍持续存在，并严重影响学习成绩或日常生活；\n3  不是由于视、听觉缺陷、神经系统疾病，或运动系统障碍所致。"}],"nameEn":"Specific developmental disorder of motor function"},{"code":"75.1","name":"儿童孤独症","block":"7 精神发育迟滞与童年和少年期心理发育障碍","blockEn":"Mental retardation, and disorders of psychological development with onset usually occurring in childhood and adolescence","criteria":[{"section":"症状标准","text":"有下列1、2、3 项中，至少有7 条，且1 至少有2 条2、3 项至少各有1 条：\n1  人际交往存在质的损害，至少2 条：\n①对集体游戏缺乏兴趣，孤独，不能对集体的欢乐产生共鸣；\n②缺乏与他人进行交往的技巧，不能以适合其智龄的方式与同龄人建立伙伴关系，如仅以拉人、推人、搂抱作为与同伴的交往方式；\n③自娱自乐，与周围环境缺少交往，缺乏相应的观察和应有的情感反应（包括对父母的存在与否亦无相应反应）；\n④不会恰当地运用眼对眼的注视、以及用面部表情，手势、姿势与他人交流；\n⑤不会做扮演性游戏和模仿社会的游戏（如不会玩过家家等）；\n⑥当身体不适或不愉快时，不会寻求同情和安慰，对别人的身体不适或不愉快也不会关心和安慰；\n2  言语交流存在质的损害，主要为语言运用功能的损害；\n①口语发育延迟或不会作用语言表达，也不会用手势、模仿等与他人沟通；\n②语言理解能力明显受损，常听不懂指令，不会表达自己的需要和痛苦，很少提问，对别人的话也缺乏反应；\n③学习语言有困难，但常有无意义的模仿言语或反响式言语，应用代词混乱；\n④ 经常重复使用与环境无关的言词或不时发出怪声；\n⑤有言语能力的患儿，不能主动与人交谈、维持交谈，及应对简单；\n⑥言语的声调、重音、速度、节奏等方面异常，如说话缺乏抑、扬、顿、挫，言语刻板；\n3  兴趣狭窄和活动刻板、重复，坚持环境和生活方式不变：\n① 兴趣局限，常专注于某种或多种模式，如旋转的电扇、固定的乐曲、广告词、天气预报等。\n② 活动过度，来回踱步、奔跑、转圈等；\n③拒绝改变刻板重复的动作或姿势，否则会出现明显的烦躁和不安；\n④过分依恋某些气味、物品或玩具的一部分，如特殊的气味、一张纸片、光滑的衣料、汽车玩具的轮子等，并从中得到满足；\n⑤强迫性地固着于特殊而无用的常规或仪式性动作或活动。"},{"section":"严重标准","text":"社会往功能受损。"},{"section":"病程标准","text":"通常起病于3 岁以内。"},{"section":"排除标准","text":"排除Asperger 综合征、heller 综合征、Rett 综合征、特定感受性语言障碍、儿童精神分裂症。"}],"nameEn":"Childhood autism"},{"code":"75.3","name":"Rett 综合征","block":"7 精神发育迟滞与童年和少年期心理发育障碍","blockEn":"Mental retardation, and disorders of psychological development with onset usually occurring in childhood and adolescence","criteria":[{"section":"症状标准","text":"1  起病后，以前获得的语言和社会化技能迅速丧失，多为重度智力缺损；\n2  以前已获得的目的性手部技能丧失，出现无目的、刻板、重复的动作，多为手指置于胸前不停地扭动、揉、搓等；\n3  步态不稳或躯干运动共济不良；\n4  对环境反应差，对玩具丧失兴趣，面部不时显示“社交性微笑”一样的表情；\n5  部分患儿出现咬牙、过度呼吸，如长出气、叹气。"},{"section":"严重标准","text":"社会交往功能严重受损。"},{"section":"病程标准","text":"大都起病于7~24 个月，病程进展较快，预后较差。"},{"section":"排除标准","text":"排除孤独症、神经系统变性病、先天代谢性疾病，或Heller 综合征。"}],"nameEn":"Rett's syndrome"},{"code":"75.4","name":"童年瓦解性精神障碍（Heller 综合征）","block":"7 精神发育迟滞与童年和少年期心理发育障碍","blockEn":"Mental retardation, and disorders of psychological development with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  发病后原来获得的言语、生活和社会技能迅速衰退、甚至丧失，如大小便自控能力丧失；\n2  对亲人、游戏，及相互交往等均无兴趣。通常比较兴奋，无目的性活动增加。部分患儿可出现自残行为；\n3  病前言语、人际交往，及其他生活和社会功能的发育完全正常；\n4  排除选择性缄默症、儿童精神分裂症、孤独症、Rett 综合征，或癔症性失语等。"}],"nameEn":"Childhood disintegrative disorder (Heller's syndrome)"},{"code":"75.5","name":"Asperger 综合征","block":"7 精神发育迟滞与童年和少年期心理发育障碍","blockEn":"Mental retardation, and disorders of psychological development with onset usually occurring in childhood and adolescence","criteria":[{"section":"症状标准","text":"1  人际交往障碍的显著特点是缺乏交往技巧，交往方式刻板、生硬、程式化，缺乏发展的能力；\n2  局限于刻板、重复，或不同寻常的兴趣或活动，显得比较怪僻；\n3  无明显言语与语言发育障碍，认知发育基本正常；\n4  运动技能较低，动作较笨拙。"},{"section":"严重标准","text":"社会交往功能明显受损。"},{"section":"病程标准","text":"一般到学龄期症状才明显，症状常持续存在。"},{"section":"排除标准","text":"排除儿童精神分裂症、儿童孤独症，或Heller 综合征。"}],"nameEn":"Asperger's syndrome"},{"code":"80.1","name":"注意缺陷与多动障碍（儿童多动症）","block":"8 童年和少年期的多动障碍、品行障碍、情绪障碍","blockEn":"Hyperkinetic, conduct, and emotional disorders with onset usually occurring in childhood and adolescence","criteria":[{"section":"症状标准","text":"1  注意障碍，至少有下列4 项：\n①学习时容易分心，听见任何外界声音都要去探望；\n②上课很不专心听讲，常东张西望或发呆；\n③做作业拖拉，边做边玩，作业又脏又乱，常少做或做错；\n④不注意细节，在做作业或其他活动中常常出现粗心大意的错误；\n⑤丢失或特别不爱惜东西（如常把衣服、书本等弄得很脏很乱）；\n⑥难以始终遵守指令，完成家庭作业或家务劳动等；\n⑦做事难于持久，常常一件事没做完，又去干别的事；\n⑧与他说话时，常常心不在焉。似听非听；\n⑨ 在日常活动中常常丢三拉四；\n2  多动，至少有下列4 项：\n①需要静坐的场合难于静坐或在座位上扭来扭去；\n②上课时常小动作，或玩东西或，与同学讲悄悄话；\n③话多，好插嘴，别人问话未完就抢着回答；\n④十分喧闹，不能安静地玩耍；\n⑤难以遵守集体活动的秩序和纪律，如游戏时抢着上场，不能等待；\n⑥干扰他人的活动；\n⑦好与小朋友打逗，易与同学发生纠纷，不受同伴欢迎；\n⑧容易兴奋和冲动，有一些过火的行为；\n⑨在不适当的场合奔跑或登高爬梯，好冒险，易出事故。"},{"section":"严重标准","text":"对社会功能（如学业成绩、人际关系等）产生不良影响。"},{"section":"病程标准","text":"起病于7 岁前（多在3 岁左右），符合症状标准和严重标准至少已6 个月。"},{"section":"排除标准","text":"排除精神发育迟滞、广泛发育障碍、情绪障碍。"}],"nameEn":"Attention deficit and hyperactivity disorder"},{"code":"80.2","name":"多动症合并品行障碍","block":"8 童年和少年期的多动障碍、品行障碍、情绪障碍","blockEn":"Hyperkinetic, conduct, and emotional disorders with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"必须同时符合多动与注意缺陷障碍和品行障碍的诊断标准。"}],"nameEn":"Hyperkinetic conduct disorder"},{"code":"81.1","name":"反社会性品行障碍","block":"8 童年和少年期的多动障碍、品行障碍、情绪障碍","blockEn":"Hyperkinetic, conduct, and emotional disorders with onset usually occurring in childhood and adolescence","criteria":[{"section":"症状标准","text":"1  至少有下列3 项：\n①经常说谎（不是为了逃避惩罚）；\n②经常暴怒，好发脾气；\n③常怨恨他人，怀恨在心，或心存报复；\n④常拒绝或不理睬成人的要求或规定，长期严重的不服从；\n⑤常因自己的过失或不当行为而责怪他人；\n⑥常与成人争吵，常与父母或老师对抗；\n⑦经常故意干扰别人。\n2  至少有下列2 项：\n①在小学时期即经常逃学（1 学期达3 次以上）；\n②擅自离家出走或逃跑至少2 次（不包括为避免责打或性虐待而出走）；\n③不顾父母的禁令，常在外过夜（开始于13 岁前）；\n④参与社会上的不良团伙，一起干坏事；\n⑤故意损坏他人财产，或公共财物；\n⑥常常虐待动物；\n⑦常挑起或参志斗殴（不包括兄弟姐妹打架）；\n⑧反复欺负他人（包括采用打骂、折磨、骚扰及长期威胁等手段）。\n3  至少有下列1 项：\n①多次在家中或在外面偷窃贵重物品或大量钱财；\n②勒索或抢劫他人钱财，或入室抢劫；\n③强迫与他人发生性关系，或有猥亵行为；\n④对他人进行躯体虐待（如捆绑、刀割、针刺、烧烫等）；\n⑤持凶器（如刀、棍棒、砖、碎瓶子等）故意伤害他人；\n⑥故意纵火。\n4  必须同时符合以上第1、2、3 项标准。"},{"section":"严重标准","text":"日常生活和社会功能（如社交、学习，或职业功能）明显受损。"},{"section":"病程标准","text":"符合症状标准和严重标准至少已6 个月。"},{"section":"排除标准","text":"排除以社会生人格障碍、躁狂发作、抑郁发作、广泛发育障碍，或注意缺陷与多动障碍等。"}],"nameEn":"Dissocial conduct disorder"},{"code":"81.2","name":"对立违抗性障碍","block":"8 童年和少年期的多动障碍、品行障碍、情绪障碍","blockEn":"Hyperkinetic, conduct, and emotional disorders with onset usually occurring in childhood and adolescence","criteria":[{"section":"症状标准","text":"1  至少有下列3 项：\n①经常说谎（不是为了逃避惩罚）；\n②经常暴怒，好发脾气；\n③常怨恨他人，怀恨在心，或心存报复；\n④常拒绝或不理睬成人的要求或规定，长期严重的不服从；\n⑤常因自己的过失或不当行为而责怪他人；\n⑥常与成人争吵，常与父母或老师对抗；\n⑦经常故意干扰别人。\n2  肯定没有下列任何1 项：\n①多次在家中或在外面偷窃贵重物品或大量钱财；\n②勒索或入室抢劫他人钱财，或入室抢劫；\n③强迫与他人发生性关系，或有猥亵行为；\n④对他人进行躯体虐待（如捆绑、刀割、针刺、烧烫等）；\n⑤持凶器（如刀、棍棒、砖、碎瓶子等）故意伤害他人；\n⑥故意纵火。"},{"section":"严重标准","text":"上述症状已形成适应不良，并与发育水平明显不一致。"},{"section":"病程标准","text":"符合症状标准和严重标准至少已6 个月。"},{"section":"排除标准","text":"排除反社会性品行障碍、反社会性人格障碍、躁狂发作、抑郁发作、广泛发育障碍，或注意缺陷与多动障碍等。"}],"nameEn":"Oppositional defiant disorder"},{"code":"83.1","name":"儿童分离性焦虑症","block":"8 童年和少年期的多动障碍、品行障碍、情绪障碍","blockEn":"Hyperkinetic, conduct, and emotional disorders with onset usually occurring in childhood and adolescence","criteria":[{"section":"症状标准","text":"至少有下列3 项：\n1  过分担心依恋对象可能遇到伤害，或害怕依恋对象一去不复返；\n2  过分担心自己会走失、被绑架、被杀害，或住院，以致与依恋对象离别；\n3  因不愿离开依恋对象而不想上学或拒绝上学；\n4  非常害怕一人独处，或没有依恋对象陪同绝不外出，宁愿呆在家里；\n5  没有依恋对象在身边时不愿意或拒绝上床就寝；\n6  反复做噩梦，内容与离别有关，以致夜间多次惊醒；\n7  与依恋对象分离前过分担心，分离时或分离后出现过度的情绪反应，如烦躁不安、哭喊、发脾气、痛苦、淡漠，或退缩；\n8  与依恋对象分离时反复出现头痛、恶心、呕吐等躯体症状，但无相应躯体疾病。"},{"section":"严重标准","text":"日常生活和社会功能受损。"},{"section":"病程标准","text":"起病于6 岁前，符合症状标准和严重标准至少已1 个月。"},{"section":"排除标准","text":"不是由于广泛发育障碍、精神分裂症、儿童恐惧症，及具有焦虑症状的其他疾病所致。"}],"nameEn":"Separation anxiety disorder of childhood"},{"code":"83.2","name":"儿童恐惧症（儿童恐怖症）","block":"8 童年和少年期的多动障碍、品行障碍、情绪障碍","blockEn":"Hyperkinetic, conduct, and emotional disorders with onset usually occurring in childhood and adolescence","criteria":[{"section":"症状标准","text":"对日常生活中的一般客观事物和情境产生过分的恐惧情绪，出现回避、退缩行为。"},{"section":"严重标准","text":"日常生活和社会功能受损。"},{"section":"病程标准","text":"符合症状标准和严重标准至少已1 个月。"},{"section":"排除标准","text":"不是由于广泛性焦虑障碍、精神分裂症、心境障碍、癫痫所致精神障碍、广泛发育障碍等所致。"}],"nameEn":"Phobic anxiety disorder of childhood"},{"code":"83.3","name":"儿童社交恐惧症","block":"8 童年和少年期的多动障碍、品行障碍、情绪障碍","blockEn":"Hyperkinetic, conduct, and emotional disorders with onset usually occurring in childhood and adolescence","criteria":[{"section":"症状标准","text":"1  与陌生人（包括同龄人）交往时，存在持久的焦虑，有社交回避行为；\n2  与陌生人交往时，患儿对其行为有自我意识，表现出尴尬或过分关注；\n3  对新环境感到痛苦、不适、哭闹、不语或退出；\n4  患儿与家人或熟悉的人在一起时，社交关系良好。"},{"section":"严重标准","text":"显著影响社交（包括与同龄人）功能，导致交往受限。"},{"section":"病程标准","text":"符合症状标准和严重标准至少已1 个月。"},{"section":"排除标准","text":"不是由于精神分裂症、心境障碍、癫痫所致精神障碍、广泛性焦虑障碍等所致。"}],"nameEn":"Social anxiety disorder of childhood"},{"code":"83.91","name":"儿童广泛焦虑症","block":"8 童年和少年期的多动障碍、品行障碍、情绪障碍","blockEn":"Hyperkinetic, conduct, and emotional disorders with onset usually occurring in childhood and adolescence","criteria":[{"section":"症状标准","text":"1  以烦躁不安、整日紧张、无法放松为特征，并至少有下列2 项：\n①易激惹，常发脾气，好哭闹；\n②注意力难于集中自，觉脑子里一片空白；\n③担心学业失败或交友受到拒绝；\n④感到易疲倦、精疲力竭；\n⑤肌肉紧张感；\n⑥食欲不振，恶心或其他躯体不适；\n⑦睡眠紊乱（失眠、易醒、思睡却又睡不深等）；\n2  焦虑与担心出现在2 种以上的场合、活动，或环境中；\n3  明知焦虑不好，但无法自控。"},{"section":"严重标准","text":"社会功能明显受损。"},{"section":"病程标准","text":"起病于18 岁前，符合症状标准和严重标准至少已6 个月。"},{"section":"排除标准","text":"不是由于药物、躯体病症（如甲状腺机能亢进），及其他精神疾病或发育障碍所致。"}],"nameEn":"Generalized anxiety disorder of childhood"},{"code":"84.1","name":"选择性缄默症","block":"8 童年和少年期的多动障碍、品行障碍、情绪障碍","blockEn":"Hyperkinetic, conduct, and emotional disorders with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  在某种或多种特定社交场合（如学校）长时间拒绝说话，得在另一些场合说话正常或接近正常，其言语理解和表达能力正常。\n2  症状至少已持续1 个月，但不包括初入学的第1 个月；\n3  排除言语技能发育障碍、广泛发育障碍、精神分裂症及其他精神病性障碍。"}],"nameEn":"Elective mutism"},{"code":"84.2","name":"儿童反应性依恋障碍","block":"8 童年和少年期的多动障碍、品行障碍、情绪障碍","blockEn":"Hyperkinetic, conduct, and emotional disorders with onset usually occurring in childhood and adolescence","criteria":[{"section":"症状标准","text":"1  在社交关系中，表现为过度抑制、过分警惕、明显的矛盾反应（如患儿对养育者的安抚同时出现亲近、冷淡、回避和违抗），或缺乏情感反应、退缩、情绪紊乱，对自己或他人的痛苦表现攻击反应，或恐惧性过度警觉；\n2  有时在与正常成年人交往过程中，有一定的社义应答和反应能力。"},{"section":"严重标准","text":"在大多数场合，社交关系明显障碍。"},{"section":"病程标准","text":"起病于5 岁前，符合症状标准和严重标准至少已1 个月。"},{"section":"排除标准","text":"排除精神发育迟滞广泛发育障碍。"}],"nameEn":"Reactive attachment disorder of childhood"},{"code":"85.1","name":"短暂性抽动障碍（抽动症）","block":"8 童年和少年期的多动障碍、品行障碍、情绪障碍","blockEn":"Hyperkinetic, conduct, and emotional disorders with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  有单个或多个运动抽动或发声抽动，常表现为眨眼、扮鬼脸或头部抽动等简单抽动；\n2  抽动天天发生，1 天多次，至少已持续2 周，但不超过12 个月，某些患儿的抽动只有单次发作，另一些可在数月内交替发作；\n3  18 岁前起病，以4~7 岁儿童最常见；\n4  不是由于Tourette 综合征、小舞蹈病、药物或神经系统其他疾病所致。"}],"nameEn":"Transient tic disorder"},{"code":"85.2","name":"慢性运动或发声抽动障碍","block":"8 童年和少年期的多动障碍、品行障碍、情绪障碍","blockEn":"Hyperkinetic, conduct, and emotional disorders with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  不自主运动抽动或发声，可以不同时存在，常1 天发生多次，可每天或间断出现；\n2  在1 年中没有持续2 个月以上的缓解期；\n3   18 岁前起病，至少已持续1 年；\n4  不是由于Tourette 综合征、小舞蹈病、药物或神经系统其他疾病所致。"}],"nameEn":"Chronic motor or vocal tic disorder"},{"code":"85.3","name":"Tourette 综合征（发声与多种运动联合抽动障碍）","block":"8 童年和少年期的多动障碍、品行障碍、情绪障碍","blockEn":"Hyperkinetic, conduct, and emotional disorders with onset usually occurring in childhood and adolescence","criteria":[{"section":"症状标准","text":"表现为多种运动抽动和一种或多种发声抽动，多为复杂性抽动，二者多同时出现。抽动可在短时间内受意志控制，在应激下加剧，睡眠时消失。"},{"section":"严重标准","text":"日常生活和社会功能明显受损，患儿感到十分痛苦和烦恼。"},{"section":"病程标准","text":"18 岁前起病，症状可延续至成年，抽动几乎天天发生，1 天多次，至少已持续1 年以上，或间断发生，且1 年中症状缓解不超过2 个月。"},{"section":"排除标准","text":"不能用其他疾病来解释不自主抽动和发声。"}],"nameEn":"Tourette syndrome"},{"code":"86.1","name":"非器质性遗尿症","block":"8 童年和少年期的多动障碍、品行障碍、情绪障碍","blockEn":"Hyperkinetic, conduct, and emotional disorders with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  年龄有5 周岁以上或智龄在4 岁以上，不能自控排尿而尿床或尿裤；\n2  每月至少有2 次遗尿，至少已3 个月，遗尿可作为正常婴儿尿失禁的异常伸延，也可在学会控制小便之后才发生；\n3  不是由于神经系统损害、癫痫发作、泌尿道结构异常等器质性疾病所致，也没有严重的智力低下或其他精神病。"}],"nameEn":"Nonorganic enuresis"},{"code":"86.2","name":"非器质性遗粪症","block":"8 童年和少年期的多动障碍、品行障碍、情绪障碍","blockEn":"Hyperkinetic, conduct, and emotional disorders with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  年龄或智龄在4 岁以上，反复出现在不恰当的地方排便（如裤子里、地板上），大便性状通常正常或接近正常；\n2  每月至少有1 次遗粪，至少已6 个月；\n3  不是由于精神发育迟滞、脊髓神经病变、意识障碍、腹泻，或肛门括肌功能障碍所致。"}],"nameEn":"Nonorganic encopresis"},{"code":"86.3","name":"婴幼儿和童年喂食障碍","block":"8 童年和少年期的多动障碍、品行障碍、情绪障碍","blockEn":"Hyperkinetic, conduct, and emotional disorders with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  持续进食不当，或持续反刍或反胃；\n2  在6 岁前起病，至少在1 个月内体重无变化或下降，或有其他明显的健康问题；\n3  排除影响进食的其他器质性疾病和精神障碍。"}],"nameEn":"Feeding disorder of infancy and childhood"},{"code":"86.4","name":"婴幼儿和童年异食癖","block":"8 童年和少年期的多动障碍、品行障碍、情绪障碍","blockEn":"Hyperkinetic, conduct, and emotional disorders with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  进食不可作为食物的东西（如泥土、肥皂等）；\n2  症状每周至少2 两，至少已1 个月；\n3  实际年龄及智龄在2 岁以上；\n4  并非其他精神病或智力障碍所致，且此种进食行为并不符合当地习惯或传统。"}],"nameEn":"Pica of infancy and childhood"},{"code":"86.5","name":"刻板性运动障碍","block":"8 童年和少年期的多动障碍、品行障碍、情绪障碍","blockEn":"Hyperkinetic, conduct, and emotional disorders with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  刻板运动达到躯体受损的程度或显著干扰患儿的正常活动；\n2  症状至少已1 个月；\n3  不是由于任何其他精神病或行为障碍所致。\n4  如果系精神发育迟滞的伴发症状，此时对两种障碍都需编码。"}],"nameEn":"Stereotyped movement disorders"},{"code":"86.6","name":"口吃","block":"8 童年和少年期的多动障碍、品行障碍、情绪障碍","blockEn":"Hyperkinetic, conduct, and emotional disorders with onset usually occurring in childhood and adolescence","criteria":[{"section":"诊断标准","text":"1  经常反复出现语音、音节、单词重复、延长，频繁出现停顿，使言语不流畅，但言语表达的内容无障碍；\n2  症状至少已3 个月；\n3  不是由于神经系统疾病、抽动障碍和精神病性言语零乱所致。"}],"nameEn":"Stuttering"},{"code":"90","name":"待分类的精神病性障碍","block":"9 其他精神障碍和心理卫生情况","blockEn":"Other mental disorders and psychological health conditions","criteria":[{"section":"诊断标准","text":"1  有精神病性症状的表现；\n2  因病史不详，或无法直接进行精神状况检查，或其临床表现不符合任何特定的精神障碍的诊断标准。"}],"nameEn":"Unspecified psychotic disorder"},{"code":"91","name":"待分类的非精神病性精神障碍","block":"9 其他精神障碍和心理卫生情况","blockEn":"Other mental disorders and psychological health conditions","criteria":[{"section":"诊断标准","text":"1  有非精神病性精神症状表现。\n2  因病史不详，或无法直接进行精神状况检查，或其临床表现不符合任何特定的精神障碍的诊断标准。"}],"nameEn":"Unspecified nonpsychotic mental disorder"},{"code":"92.1","name":"无精神病","block":"9 其他精神障碍和心理卫生情况","blockEn":"Other mental disorders and psychological health conditions","criteria":[{"section":"诊断标准","text":"资料详实，检查周到，未发现任何精神病性症状，但可有下列表现之一：\n1  有某些偏离正常的思想、情感反应或行为，但不是人格障碍或轻度精神发育迟滞，也不符合任何精神障碍的诊断标准；\n2  伪装精神病史，模拟精神症状表现，但本人不承认伪装或症状依然存在，诊断诈病证据不足，且可以排除各种特定的精神障碍。"}],"nameEn":"Without psychiatric disorder"},{"code":"92.2","name":"诈病","block":"9 其他精神障碍和心理卫生情况","blockEn":"Other mental disorders and psychological health conditions","criteria":[{"section":"诊断标准","text":"为了逃避外界某种不利于个人的情境，摆脱某种责任或获得某种个人利益，故意模拟或夸大躯体或精神障碍或伤残的行为。具有下述特点：\n1  有明显的装病动机的目的；\n2  症状表现不符合任何一种疾病的临床相，躯体症状或精神症状中的幻觉、妄想，及思维障碍，情感与行为障碍等均不符合疾病的症状表现规律；\n3  对躯体或精神状况检查通常采取回避、不合作、造假行为或敌视态度，回答问题时，反应时间常延长，对治疗不合作，暗示治疗无效；\n4  病程不定；\n5  社会功能与躯体功能障碍的严重程度比真实疾病重，主诉比实际检查所见重；\n6  有伪造病史或疾病证明，或明显夸大自身症状的证据。\n7  病人一旦承认伪装，随即伪装症状的消失，是建立可靠诊断的必要条件。"}],"nameEn":"Malingering"},{"code":"92.5","name":"病理性激情","block":"9 其他精神障碍和心理卫生情况","blockEn":"Other mental disorders and psychological health conditions","criteria":[{"section":"诊断标准","text":"1  以极难自控的激动或暴怒情绪发作，伴有明显意识障碍与冲动行为；\n2  有削弱朋脑代偿功能与自控能力的脑病史（如脑缺血、缺氧、炎症、外伤、癫痫史），以及实验室检查证明有脑部形态或功能异常；\n3  起病突然、病程短暂，数分钟至数小时后自行恢复，发作后对病中经历部分或完全遗忘；\n4  应排除器质性精神障碍、躯体疾病或精精神活性物质和非成瘾物质所致精神障碍的人格改变或精神病性症状。"}],"nameEn":"Pathological passion"},{"code":"92.6","name":"病理性半醒状态","block":"9 其他精神障碍和心理卫生情况","blockEn":"Other mental disorders and psychological health conditions","criteria":[{"section":"诊断标准","text":"1  发生于睡眠过程中，多数在凌晨1~4 时发生；\n2  入睡前常有过度疲劳或精神应激因素，深睡后受到干扰而觉醒不完全；\n3  以意识不清、片断错觉、幻觉、惊恐与愤怒情绪、非协调性精神运动兴奋、攻击行为为特征；\n4  起病突然，病程短暂，数十分钟至数小时后自行恢复常态；醒后对病中的经历大多遗忘。"}],"nameEn":"Pathological drunkenness"},{"code":"92.31","name":"自杀死亡","block":"9 其他精神障碍和心理卫生情况","blockEn":"Other mental disorders and psychological health conditions","criteria":[{"section":"诊断标准","text":"1  有充分依据可以断定死亡的结局系故意采取自我致死的行为所致；\n2  只有自杀意念而未实行者不采用此诊断。并无自杀意念，但由于误服剧毒药物，误受伤害等原因致死者不采用此诊断。伪装自杀亦不属此诊断；\n3  自杀者可无精神障碍，如自杀时已存在某种精神障碍，则并列诊断。"}],"nameEn":"Completed suicide"}];
